window.BC=window.BC||{};window.BC.meta={"CAISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL": "Coal", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["LA_BASIN", "NP15", "SDGE", "SP15_rest", "ZP26"]}, "ERCOT": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"]}, "MISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["MISO-East", "MISO-Illinois", "MISO-Indiana", "MISO-Plains", "MISO-South", "MISO-West"]}, "NEISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["Boston", "Central", "Connecticut", "North"]}, "NYISO": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "years": [2023, 2024, 2025], "zones": ["Capital_Hudson", "Long_Island", "Lower_Hudson", "NYC", "Upstate_West"]}, "PJM": {"groupLabel": {"CC_CHP": "CC CHP", "CC_REGULAR": "CC Regular", "COAL_BIT": "Coal Bituminous", "COAL_PRB": "Coal PRB", "COAL_WC": "Coal Waste", "CT_CHP": "CT CHP", "CT_PEAKER": "CT Peaker", "OTHER_FOSSIL": "Other Fossil", "ST_CHP": "Steam CHP", "ST_GAS": "Steam Gas"}, "groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "years": [2023, 2024, 2025], "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"]}};window.BC.manifest=[{"date": "2026-07-03", "definition": "(PROBE) Cross-ISO band de-leakage (audit C-11/C-13, rule #24): MISO's inherited ERCOT gas bands (CC_CHP, CT_CHP, ST_GAS, and the CT_PEAKER committed 1.55 / econ 1.27/1.98 'generic shape') are neutralized to 1.0; MISO-grounded CC_REGULAR (committed 1.20 part-load premium, flat 0.95/1.08 baseload econ), the MISO offer-cap CT peak 4.0, and the physical F-class CC duct-burner peak 2.25 are kept; *_INTERMEDIATE (measured-shape) and coal untouched. EFFECT vs keeper miso-39 (not re-tuned, rule #1): dropping the ERCOT 1.55 CT start-hurdle to 1.0 lets peakers run, so the CT_PEAKER under-run SHRINKS -20.5->-12.0 TWh (2023) / -18.2->-9.2 (2024); the cheaper neutral bids lower C3a mean LMP to -9.8/-15.7/-19.6% (was -8.5/-13.6/-16.9%). PRE-EXISTING MISO root causes unchanged by this scrub: the CC_REGULAR +44 TWh over-run (measured-flat econ body) and the 0-hour scarcity tail (missing RDC/ELMP co-opt) \u2014 both open items, not band-addressable.", "file": "frontend/data/backcast/runs/2026-07-03-miso-40-band-deleak.js", "id": "2026-07-03-miso-40-band-deleak", "iso": "MISO", "label": "miso 40 band deleak", "shorthand": "miso-40-band-deleak", "years": [2023, 2024, 2025]}, {"date": "2026-07-03", "definition": "STALE vs current MISO keeper 2026-07-06-miso-44-wefor-neutral (bundle MISO/miso_44_wefor_neutral) \u2014 this probe replays the superseded miso_39_reserve_pergen (miso-39-reserve-pergen) keeper, itself superseded once already (miso-41-ct-evening, 2026-07-05) before the current swap. No successor statmode probe has been registered against any later MISO keeper (G-10 gap register: 'PJM/MISO statmode twins stale after 07-05 keeper swaps, unflagged') \u2014 a fresh same-SHA replay against miso_44_wefor_neutral is queued, not done here. Retained for history. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper miso_39_reserve_pergen (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-03-miso-statmode-d-7.js", "id": "2026-07-03-miso-statmode-d-7", "iso": "MISO", "label": "miso statmode d 7", "shorthand": "miso-statmode-d-7", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-41-ct-evening-ablation", "date": "2026-07-05", "definition": "MISO 41 (KEEPER, supersedes miso-39): miso-40 de-leaked offer curve (neutral 1.0 generic gas bands, no inherited ERCOT multipliers) + CT_PEAKER reliability-floor EVENING WINDOW [15,21]. Fixes the C7/rule-13 D-4 failure carried by miso-39: the hot-day (tmax) CT reliability limb was floored a flat 38 MW in all 24 h (68-70% off-window, binding overnight when CT CF~0) because the MISO limb carried no sub-daily window; adding start_hour=15/end_hour=21 (matching the D-4 justified window [15,22) and the CAISO CT limbs) gates it to the afternoon-evening net-load ramp. RESULT: legitimacy diagnostics flip Overall FAIL->PASS (D-4 CT_PEAKER 0% off-window all 3 yrs; D-1/D-2/D-5/D-9 hold); zero new fitted parameter (the window is a structural shape param, derive-script-emitted). Mean LMP 28.67/25.99/34.47 (2023/24/25); vs miso-39 29.10/26.60/35.59 the de-leak trims prices ~0.4-1.1/MWh so C3a is modestly worse (-9.8/-15.6/-19.5% vs -8.5/-13.6/-16.9%), CO2 PASS x3 and the 0-h scarcity tail (C3c) unchanged. PROMOTED because strictly more structurally faithful: it clears a HARD legitimacy gate the incumbent violates (a rule-13 off-window floor) and removes the foreign ERCOT band leak, nothing tuned. OPEN ROOT CAUSES (logged, not fixed - rules #1/#11, results/calibration/FINDING-miso-burndown-2026-07.md): (A) coal (marginal ~94% of hours) is offered ~$4-5/MWh BELOW its measured F923 delivered SRMC by the gas-keyed passthrough sigmoid (model LMP $25.9 < coal committed measured SRMC $28.3 < actual $30.8 = coal econ_body measured $30.4), driving both the coal over-run (C1/C2) and the low price (C3a) - needs a measured take-or-pay-grounded bound on the marginal coal tranche, not a residual re-tune; (B) missing RDC/ELMP scarcity price (C3c). The neutral-1.0 gas committed bands sit AT the 1.0x SRMC floor (no rule-17 violation) and are immaterial since gas is never marginal - MISO does not need grounded gas bands as the burndown lever.", "file": "frontend/data/backcast/runs/2026-07-05-miso-41-ct-evening.js", "id": "2026-07-05-miso-41-ct-evening", "iso": "MISO", "label": "miso 41 ct evening", "market_story": "The evening-window CT_PEAKER reliability floor forces only 0.02-0.08 TWh/yr (<0.35% of the class) \u2014 a real but small hot-day evening-ramp reliability commitment, not a residual-buying floor. Zero-forcing every merchant floor confirms this directly: CT_PEAKER dispatch RISES 3.2/3.8/4.7% (2023/24/25) once the floor is removed, because it stops competing with floor-forced baseload for the same net-load hours, not falls, as a residual-buying floor would show. ST_GAS more than doubles (+63-115%) once other floors stop consuming load ahead of it. OTHER_FOSSIL's entire keeper volume (4.0/3.7/2.5 TWh/yr) disappears in the twin \u2014 that class is currently 100% floor-forced, an open root-cause item (rules #1/#11) to isolate, not fixed here. Coal subtypes and CC_REGULAR/CC_CHP move by <1.5%, confirming the keeper's floors are immaterial to the coal-vs-gas merit order the burndown finding (FINDING-miso-burndown-2026-07.md) already attributes to the passthrough-sigmoid offer curve, not to any floor.", "shorthand": "miso-41-ct-evening", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "STALE vs current NEISO keeper 2026-07-06-neiso-50-head-repro (bundle neiso49_resolve_confirm) \u2014 this r2 solve replays the neiso_ctscrub (neiso-48-ct-floor) keeper, since superseded twice (neiso-49-stgas-netload, then the current neiso-50-head-repro); it is not a same-SHA replay of the current keeper. A fresh replay against neiso49_resolve_confirm is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper neiso_ctscrub (the 2026-07-05 neiso-48-ct-floor keeper, meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe (which replayed the prior neiso-47 keeper): the R2 physical-HR CO2 basis (fff2c34) moves NEISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is near-zero, per docs/handoffs/co2-keeper-regate-2026-07-05.md). Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-neiso-statmode-d7-r2.js", "id": "2026-07-05-neiso-statmode-d7-r2", "iso": "NEISO", "label": "neiso statmode d7 r2", "shorthand": "neiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23), floors-alone config; one-delta vs nyiso-48 head-regate, all years 2023-2025. Two source-grounded narrowings: (1) the NYC CT_PEAKER 24h hot step (tmax 31.7 / 0.1833) DISABLED (r1_disabled) \u2014 the D-4 off-window binder that double-floored NYC CT on top of the windowed NYC_CT_ev ramp and bound all 24h incl. overnight where measured CAMPD NYC CT CF~=0.018 (rule 17/18); (2) the Long Island local self-supply floor NARROWED to the HB14-21 peak window (its LCR/cable-import driver binds only at the summer design-cooling peak, not overnight) \u2014 the 0.45 fraction (residual-identified, issue #1345) is UNCHANGED, only the hours it binds. RESULT: C7 diurnal (D-1) FAIL->PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 2.393). CT_PEAKER 4.46/4.51/4.73 -> 3.70/2.84/3.86 TWh (actual 2.26/2.13/2.84), C1 CT_PEAKER FAIL->in band; free-class stays 9/10 (remaining fail = 2024 ST_GAS -3.48, the pre-existing steam under-run). self-supply CT forcing HALVED (1.84/2.87/1.86 -> 0.90/1.23/0.89 TWh); reliability-floor CT overnight energy = 0.000 (was ~0.18 from the NYC step). NOT a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 25.6/34.1/25.1%) and C3a -16.2/-15.5/-13.6% / C3c 0/0/7h still FAIL \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure (CT peakers stay economically idle without it, so the floors carry the CT commitment). D-4 residual (~35%) is entirely hour 14 (0 overnight) \u2014 a boundary artifact between D-4's hardcoded canonical CT window h15-21 and the source-derived NYISO ramp HB14-21. Rules 1/17/18/23; #1344 out of scope (parallel LP-core refactor).", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-51-floor-rederive.js", "id": "2026-07-05-nyiso-51-floor-rederive", "iso": "NYISO", "label": "nyiso 51 floor rederive", "shorthand": "nyiso-51-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "(PROBE \u2014 KEEPER-CANDIDATE pending #1344, NOT a keeper swap) NYISO CT/ST reliability-floor re-derivation (rule 17/18/23) + nyiso_downstate_ct_gas_basis=True (the PR #1427 delivered-fuel city-gate premium, kept default-off); one-delta vs nyiso-48 head-regate + the floors config, all years 2023-2025. Floors: NYC CT 24h hot step DISABLED (r1_disabled, D-4 off-window binder) + LI local self-supply NARROWED to the HB14-21 peak window (0.45 level unchanged; hours only). RESULT: strongest candidate yet. CT_PEAKER 4.46/4.51/4.73 -> 2.02/2.33/2.91 TWh (actual 2.26/2.13/2.84) \u2014 near-exact all 3 years; C1 CT_PEAKER in band, free-class 9/10 (remaining fail = 2024 ST_GAS -3.30, the pre-existing steam under-run). C7 diurnal (D-1) PASS all years (2024 CT_PEAKER off-peak cv_ratio 0.454 -> 3.47, r 0.84). self-supply CT forcing halved; reliability-floor CT overnight energy = 0.000. NOT YET a keeper: rule-20 D-2 CT_PEAKER forced-share still >10% (reliability alone 45.8/54.5/39.3% \u2014 HIGHER share because the dearer downstate gas shrinks the economic-CT denominator) and C3a -13.5/-14.7/-12.5% (improved from -17/-18/-15 by the gas premium, still out of band) / C3c 0/0/7h \u2014 both now cleanly the missing #1344 peaker-scarcity/reserve price structure, the SAME root cause (CT peakers stay economically idle without it, so the floors carry the CT commitment and the tail never prices). D-4 residual (~34%) is entirely hour 14 (0 overnight) \u2014 the h15-21 vs HB14-21 window-boundary artifact, not off-window binding. Recommended eventual NYISO keeper config once #1344 lands. Rules 1/13/17/18/23; keeper stays nyiso-41 STALE-VS-HEAD, keepers.json unchanged.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-52-floor-rederive.js", "id": "2026-07-05-nyiso-52-floor-rederive", "iso": "NYISO", "label": "nyiso 52 floor rederive", "shorthand": "nyiso-52-floor-rederive", "years": [2023, 2024, 2025]}, {"date": "2026-07-05", "definition": "STALE vs current NYISO keeper 2026-07-06-nyiso-53-li-tsl (bundle nyiso53_litsl_v2) \u2014 this r2 solve replays the superseded nyiso41_hubprices (nyiso-41-hub-prices) keeper; it addressed only the R2 CO2-basis confound (fff2c34) and the B-NYI-1 offer-curve de-leak, not the keeper swap to nyiso-53 (Zone-K LCR/TSL mechanism + v2 measured plant CO2 rates) \u2014 it is not a same-SHA replay of the current keeper (G-10 gap register: 'CAISO/NYISO r2 confounded with offer-curve merges, no same-SHA keeper replay'). A fresh replay against nyiso53_litsl_v2 is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper nyiso41_hubprices (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. RE-SOLVED at HEAD (2026-07-05) superseding the 2026-07-03 probe: the R2 physical-HR CO2 basis (fff2c34) moves NYISO's merit order (carbon-priced ISO) so the prior solve was stale; C5a CO2 vs eGRID still PASSes (R2 effect on this ISO's CO2 verdict is <0.1%, per docs/handoffs/co2-keeper-regate-2026-07-05.md). CAVEAT: this HEAD replay inherits the keeper's then-current offer state, including the B-NYI-1 `_NYISO_OFFER_CURVE` de-leak (CT_PEAKER peak 13.15->4.0, econ_low/econ_high 1.27/1.98->1.0/1.0; CC_REGULAR econ_high 1.21->1.0, merge a4c219e, 2026-07-05 re-gate) \u2014 recorded here, not compensated for; see docs/calibration-log.md 2026-07-05 NYISO keeper HEAD re-gate entry. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-05-nyiso-statmode-d7-r2.js", "id": "2026-07-05-nyiso-statmode-d7-r2", "iso": "NYISO", "label": "nyiso statmode d7 r2", "shorthand": "nyiso-statmode-d7-r2", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "STALE vs current CAISO keeper 2026-07-06-caiso-58-v2-regate (bundle caiso58_v2_regate) \u2014 despite the \"v2\" label this probe still replays the superseded caiso51_firm_base (caiso-51-firm-base) keeper (the \"v2\" refers to a code/basis delta, not a keeper re-gate); it is not a same-SHA replay of the current keeper (G-10 gap register: 'CAISO/NYISO r2 confounded with offer-curve merges, no same-SHA keeper replay'). A fresh replay against caiso58_v2_regate is queued, not done here. Original definition: D-7 statistical-mode A/B probe: byte-faithful replay of keeper caiso51_firm_base (meta.json) with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False). Structural model + realized annual Henry Hub gas price unchanged. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-06-caiso51-statmode-v2.js", "id": "2026-07-06-caiso51-statmode-v2", "iso": "CAISO", "label": "caiso51 statmode v2", "shorthand": "caiso51-statmode-v2", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-05-miso-41-ct-evening) D-3 zero-forcing ablation twin of the miso-41-ct-evening keeper (CLAUDE.md rule 20): the miso-41 recipe (de-leaked default offer curve + CT_PEAKER evening-window reliability floor) verbatim, same 2023-2025 span, with every merchant floor/bridge neutralized via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam-following, coal take-or-pay). Keeper-vs-twin per-class delta (real solved dispatch, not the D-2 fleet_only reconstruction): CT_PEAKER +3.2/+3.8/+4.7% (2023/24/25) \u2014 confirms the miso-41 evening-window floor is immaterial once fully removed, matching its own tiny 0.02-0.08 TWh/yr forced share; ST_GAS +115/+95/+63% \u2014 no longer crowded out once other floors stop consuming load; OTHER_FOSSIL -100% all years (4.0/3.7/2.5 TWh/yr to zero) \u2014 entirely floor-forced, an open root-cause item (rules #1/#11: which mechanism carries it is not yet isolated); coal subtypes -0.7% to -1.2%, CC_REGULAR/CC_CHP within \u00b10.4%. Registered alongside the keeper for the E9 keeper-vs-twin delta; not a keeper candidate.", "file": "frontend/data/backcast/runs/2026-07-06-miso-41-ct-evening-ablation.js", "id": "2026-07-06-miso-41-ct-evening-ablation", "iso": "MISO", "label": "miso 41 ct evening (ABLATION TWIN)", "shorthand": "miso-41-ct-evening-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE \u2014 NOT a keeper swap; no LP solve) v2 emission-rate re-score of keeper miso-41-ct-evening under use_plant_emission_rates_v2=True. Dispatch/prices/generation are PROVABLY byte-identical (emission_rate enters mc only via emission_rate\u00d7carbon_price; MISO has no state carbon program and backcast carbon_price=0 \u2014 the committed runs.js carries a COMPACT CO2/fuelmix registration payload \u2014 the per-plant panels are omitted (data identical to the keeper's), and the full payload was verified byte-identical to the keeper before compaction). Only CO2 accounting moves. Re-scoring the keeper's persisted per-plant model generation (committed dashboard payload m_ann) through the v2 target-year rate map: COVERAGE 90.2/91.1/93.5% of model fossil GWh now carries a MEASURED plant-specific CO2 rate \u2014 MISO's FIRST measured rates (pre-v2 every MISO plant booked the generic heat_rate\u00d7FUEL_CO2 default; the legacy artifact is TX-only). v2-basis model CO2 235.6/231.8/269.1 Mt over covered generation (2023/24/25); on the matched plant subset the v2 basis is \u22120.53/\u22122.65/\u22123.30% vs the eGRID+CAMPD-v1 basis \u2014 small, no distortion (the larger raw-total gap is the ~7-10% not-yet-CEMS-covered generation, not a rate error). Dashboard C5a verdict UNCHANGED (reads egrid.fossil_co2_rate_map, not v2). Rules #1/#13/#15/#22: no retune, no keeper swap, holdouts untouched (only 2023-2025 read). \u00a79.6 lane L-8b.", "file": "frontend/data/backcast/runs/2026-07-06-miso-41-v2rescore-probe.js", "id": "2026-07-06-miso-41-v2rescore-probe", "iso": "MISO", "label": "miso 41 v2rescore probe", "shorthand": "miso-41-v2rescore-probe", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-42-coal-econ-ablation", "date": "2026-07-06", "definition": "MISO 42 (CANDIDATE, L-14 G-23 lever; keeper stays miso-41 pending owner call): miso-41 recipe + coal_econ_srmc_bound \u2014 the marginal (econ*/peak) coal tranches' fuel passthrough is clamped to >=1.0 so no marginal coal offer sits below the plant's measured F923 incremental delivered SRMC; the committed/must-run bands keep the contracted take-or-pay discount. Removes the passthrough sigmoid's fitted discount from tranches whose fuel is bought at market (FINDING-miso-burndown-2026-07.md Evidence 2: model LMP sat $4-5 below the cheapest measured coal tranche while coal was marginal ~94% of hours) \u2014 a DOF reduction, nothing tuned. RESULT vs miso-41: the priced-out classes wake up structurally (ST_GAS 2.9/3.3/3.4 -> 6.8/7.3/5.3 TWh; CT_PEAKER 13.4/17.3/16.9 -> 15.0/20.8/17.6; net imports 14.7/3.7/-5.1 -> 19.5/6.3/-4.6 vs actual 37.9/23.1/19.0); C3a improves all 3 years (-8.2/-13.0/-18.9% vs -9.8/-15.6/-19.5%); 2025 coal over-run improves (C2 +7.2% vs +8.8%); CO2 PASS x3; legitimacy D-gates Overall PASS (C7/C8 PASS, zero forced energy from the bound \u2014 it is an offer bound, not a floor). COSTS: coal 2023/24 under-run deepens (154.9/144.2 vs actual 175.0/167.1 \u2014 the sigmoid discount was silently compensating for missing coal self-commitment volume; the committed band is not yet sized from the measured EIA-923 Sch-5 contract share in the MISO fleet branch) and CC_REGULAR worsens +2.9/+4.3/+1.8 to +46.4/+46.8 TWh (2023/24) \u2014 confirming per FINDING-miso-cc-decomposition-2026-07.md that the CC row is the P1 commitment-posture wedge (DP-1: +34% committed CC energy vs MIP; 135.6x1.34=181.7~=model), designed (not built) in docs/multi-iso/miso-scarcity-posture-design-2026-07.md. C3c tail still 0 h (needs the posture lever). C5b 2025 (+1296.7%) is a benchmark basis artifact, not a model miss \u2014 EIA-930 MISO reports battery-only while the model side includes the 2,417 MW PS fleet whose throughput matches the eGRID net-energy-implied band (FINDING-miso-c5b-storage-benchmark-2026-07.md).", "file": "frontend/data/backcast/runs/2026-07-06-miso-42-coal-econ.js", "id": "2026-07-06-miso-42-coal-econ", "iso": "MISO", "label": "miso 42 coal econ", "market_story": "Zero-forcing twin deltas are SMALL under the SRMC bound (all classes within ~7%/1.9 TWh): CT_PEAKER +2.8/+3.2/+4.4% and ST_GAS +4.8/+6.9/+6.4% (floors off, these classes still run - they clear economically once marginal coal offers at its measured delivered SRMC, so the evening-reliability floor is commitment scaffolding, not their dispatch model); OTHER_FOSSIL +4.4-6.4% (contrast the miso-41 twin where it was 100% floor-forced and ST_GAS moved +63-115%: the bound, not the floors, now carries the mid-merit price floor); imports +1.9/+1.2/+0.9 TWh (floor-forced domestic energy was crowding out the priced seam); CC/coal families -0.1 to -1.4%. The real market runs these classes on price, and with the fitted coal discount removed the model does too - the floors' forced share collapses toward the C8 budget's spirit.", "shorthand": "miso-42-coal-econ", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-42-coal-econ", "date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-miso-42-coal-econ, PROMOTED to the MISO keeper 2026-07-06) D-3 zero-forcing ablation twin of the miso-42-coal-econ candidate keeper (CLAUDE.md rule 20): the miso-42 recipe verbatim (coal_econ_srmc_bound KEPT - it is an offer bound, not a floor), same 2023-2025 span, with every merchant floor/bridge neutralized via ScenarioConfig.as_zero_forcing_ablation (off-list from the D-2 mechanism registry), structural protected set kept (nuclear must-run, CHP steam-following, coal take-or-pay). Re-solved from scratch on HEAD ac11191 in the L-14 continuation session after the Wave-3 container died mid-twin (PR #1486 checkpoint); all MISO-affecting src is unchanged between the base run's sha 632e10d and ac11191 (NYISO/NEISO-gated or dead-constant deletions only), and the EIA-930 MISO extract backfill (a2cb5c2) added 2019-2021 rows only - the 2023-2025 slices the solve reads are unchanged. UNUSUAL DASHBOARD ROLE (updated 2026-07-06): this sidecar was originally registered purely as the E9 keeper-vs-twin diagnostic and was NOT itself a new mechanism or a keeper candidate - but keepers.json now designates THIS zero-forcing twin, rather than the base recipe, as the MISO keeper, superseding 2026-07-05-miso-41-ct-evening; the base recipe 2026-07-06-miso-42-coal-econ (bundle miso_42_coal_econ_srmc) remains separately registered as the un-ablated candidate this twin was solved to validate, and was the run actually recommended for promotion in the 2026-07-06 calibration log. Because the twin and base share the coal_econ_srmc_bound offer bound and differ only in the zero-forced merchant floors/bridges, the determination is unchanged from the base recipe: NOT-YET (current live verdict; governance gate UNATTESTED for this bundle). Per the keeper-promotion commit's own note (rule 21): because this keeper is itself the zero-forcing run, its E9 ablation-twin slot is inverted from the usual pairing - it is the forced-floors main run, 2026-07-06-miso-42-coal-econ, whose sidecar's market_story field already carries the keeper-vs-twin per-class delta this field exists to surface. Remaining provenance gap, not a text-accuracy issue: this bundle carries no calibration_attestation.json/DOF ledger of its own (audit E8) - the DOF ledger committed to date covers the base run's bundle (miso_42_coal_econ_srmc), not this ablation-twin bundle (miso_42_coal_econ_srmc-ablation) that now serves as keeper - flagged for the owner, not silently fixed here.", "file": "frontend/data/backcast/runs/2026-07-06-miso-42-coal-econ-ablation.js", "id": "2026-07-06-miso-42-coal-econ-ablation", "iso": "MISO", "label": "miso 42 coal econ (ABLATION TWIN, now MISO KEEPER)", "shorthand": "miso-42-coal-econ-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE - honesty gate FAIL, lever stays default-off) miso-43: the miso-42 recipe + miso_commitment_posture, the design-note SA pooled linear commitment-posture lever (G-25/DP-1) built this session: per non-fast-start (zone x class) pergen pool an online-capacity variable U with joint P+R<=U, CEMS-measured min-load coupling P>=mlf*U (thermal_tranches committed_pct, WWSIS-2 gap-fill), an NREL-class startup charge on dU+ (18 of 30 pools postured by the rule-18 physics gate; mlf 0.12-0.58, startup $44-100/MW), and the pergen reserve cap online-gated R<=rho(t)U. Zero fitted parameters. HONESTY GATE (SUMMARY-posture-gate.md, vs the measured MISO ASM series intaken this session, data/raw/MISO-AS): FAIL on level - modeled postured online headroom 9.9-11.1 GW vs measured cleared reserve 2.5-2.7 GW (3.7-4.2x too loose); direction only partial (daily r model-reserve-price vs spin MCP 0.00/0.20/0.31; top-20 event days same-direction 19/19/15 of 20); regional split over-weights South (34-38% vs measured 13-18%). Structural effects, verified not tuned: reserve duals fire 637/700/470 h/yr (vs 59/64/207 in miso-39) and startups now cost 102/107/139 GW*$/MW-yr of real cycling charge, but the $200 curve step still never engages (C3c tail 0 h x3) and the C1 CC row is UNCHANGED (+0.8/+0.5/+0.3 TWh vs miso-42; imports -2.1/-1.2/-0.9 TWh, slightly worse) - the LINEAR pool relaxation holds ~10 GW online at min-load ($2.19-3.52 gas makes min-load burn cheaper than the curve), capturing only a small part of the DP-1 MIP wedge. Named follow-ups: min-run/min-down rolling-window rows on U (deferred, G-40 memory-gated), the Midwest zonal family (B, still DATA-BLOCKED on the historical zonal requirement series), and a tighter posture grain. Keeper unchanged.", "file": "frontend/data/backcast/runs/2026-07-06-miso-43-commitment-posture.js", "id": "2026-07-06-miso-43-commitment-posture", "iso": "MISO", "label": "miso 43 commitment posture", "shorthand": "miso-43-commitment-posture", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "miso-44 ablation twin: zero-forcing of miso-44 (wefor already at 1.0; floors off)", "file": "frontend/data/backcast/runs/2026-07-06-miso-44-ablation.js", "id": "2026-07-06-miso-44-ablation", "iso": "MISO", "label": "miso 44 ablation", "shorthand": "miso-44-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-miso-44-ablation", "date": "2026-07-06", "definition": "miso-44: miso-42 recipe + wefor_multiplier neutralized 0.7\u21921.0 (DOF reduction, audit C-15). Root-cause: the miso-42 ablation twin scored better because wefor=0.7 was silently subsidizing CC availability (lowering thermal EFOR 30%), not because the reliability floors were harmful. Neutralizing wefor halves the CC over-run (+44\u2192+20 TWh) and improves prices (C3a from -15.6\u2192PASS in 2024). Reliability floors KEPT (all structurally sound, <0.6 TWh total forced). 6 residual-identified DOFs (vs miso-42's 7).", "file": "frontend/data/backcast/runs/2026-07-06-miso-44-wefor-neutral.js", "id": "2026-07-06-miso-44-wefor-neutral", "iso": "MISO", "label": "miso 44 wefor neutral", "market_story": "DOF reduction from miso-42: wefor_multiplier removed (0.7\u21921.0). The 0.7 haircut had no measured physical basis (audit C-15: scales THERMAL EFOR, not wind); root-cause of the miso-42 ablation-twin advantage was the twin's wefor neutralization, not its floor removal. With physical EFOR restored: CC_REGULAR drops from +44/+43 to +20/+19 TWh (2023/24), CT_PEAKER recovers to PASS, C3a price-mean 2024 recovers to PASS, C3b price-shape 2025 recovers to PASS. Coal 2025 over-run worsens (+8.8%\u2192+14.7%) as reduced CC availability shifts marginal load to coal \u2014 a known commitment-posture artifact. All reliability floor limbs retained (MISO-Indiana CT_PEAKER evening [15,21), MISO-Indiana COAL tmax, MISO-Plains ST_GAS tmax, MISO-South COAL tmax); forced energy <0.4% of any class (D-2 PASS). Legitimacy diagnostics Overall PASS.", "shorthand": "miso-44-wefor-neutral", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-neiso-50-head-repro) D-3 zero-forcing twin: identical keeper recipe, full 2023-2025 span, every merchant floor/bridge neutralized (nuclear must-run, CHP steam-following and coal take-or-pay retained). Clears the keeper's audit_keepers E9 owner-deferred exception. Keeper-vs-twin per-class deltas are small (max +-0.17 TWh: COAL_BIT -0.17/2025, CC_CHP -0.13/2025, CT_PEAKER +0.17/2025) - the keeper is not floor-dependent. NOTE: solved at 2026-07-06 main HEAD (46fb645 + measured seam-ladder recal), which post-dates the keeper's solve commit (dd85d5a); price-level differences vs the keeper's registered numbers are dominated by main drift (see neiso52 HEAD baseline), not by floor removal.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-50-ablation.js", "id": "2026-07-06-neiso-50-ablation", "iso": "NEISO", "label": "neiso 50 ablation", "shorthand": "neiso-50-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-neiso-50-ablation", "date": "2026-07-06", "definition": "KEEPER SWAP (promoted 2026-07-06, replacing neiso-49-stgas-netload): byte-reproducible re-solve of the IDENTICAL neiso-49 recipe (same run_config, reliability-floor CSV, offer bands, flags) on current main HEAD, not a structural change. neiso-49's registered numbers rested on an uncommitted, never-captured WIP edit at solve time (git.dirty=true) that produced a spurious NEISO zonal price separation (HQ_import pricing $0.31-$1.86/MWh below the mainland zones); a git bisection across the full commit range back to the keeper's base commit, including a clean checkout of that base, confirmed the separation never existed in any committed state and was purely a WIP artifact of that one session. neiso-49's bundle and ablation twin have been retired. The honest, reproducible price level is correspondingly worse than neiso-49's (C3a demand-weighted price: 2023 -8.3% -> -10.4%, 2024 -7.8% -> -8.6%, 2025 -1.6% -> -4.4%); C1 fuel-mix and C3b shape are unchanged to reproducibility noise. Determination stays CALIBRATED-WITH-CAVEATS (unchanged from neiso-49). D-3 UPDATE (2026-07-06): the previously owner-deferred zero-forcing ablation twin is now solved and registered (2026-07-06-neiso-50-ablation, bundle results/calibration/neiso49_resolve_confirm-ablation) and linked via this sidecar's \"ablation_twin\" field, clearing audit_keepers E9; see calibration_attestation.json exceptions (criterion: governance, RESOLVED 2026-07-06, was OWNER-DEFERRED (temporary)). Keeper-vs-twin per-class deltas are small (max +-0.17 TWh) \u2014 the fit is not floor-dependent (see market_story).", "file": "frontend/data/backcast/runs/2026-07-06-neiso-50-head-repro.js", "id": "2026-07-06-neiso-50-head-repro", "iso": "NEISO", "label": "neiso 50 head repro", "market_story": "Floors buy almost nothing in NEISO (max class delta +-0.17 TWh vs the zero-forcing twin): COAL_BIT (Merrimack) runs its take-or-pay/seasonal commitment pattern rather than pure merit (-0.17 TWh without the floor in 2025); CC_CHP/CT_CHP steam hosts hold output for industrial steam load (-0.13/-0.06 TWh); CT_PEAKER absorbs the small backfill when those floors are off (+0.17 TWh). No class's floor buys more than 0.2% of ISO load - the NEISO fit is carried by fuel/passthrough physics, not commitment scaffolding.", "shorthand": "neiso-50-head-repro", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE) Priced interchange re-test with measured seam ladders - audit C-6 closure. IMPORT/EXPORT_TRANCHES[NEISO] rederived from measured data only (scripts/derive_neiso_import_tranches.py): per-seam Q-Q duration coupling of the measured ISO-NE DA hub LMP with measured EIA-930 per-seam flows (HQT/NBSO/NYIS), NYISO proxy-bus anchors (NYISO_HQ opportunity cost, NYISO_NPX parity), year-keyed 2023-2025 + pooled forward ladder. Keeper recipe + --priced-interchange. P9 vs the 2026-06-12 smoke (-23.5 vs -10.3 TWh, 100% import hours): net interchange now -14.8/-8.9/-9.6 TWh vs -15.1/-10.3/-8.1 actual (-2%/-13%/+18%), duration RMSE 529/609/554 MW, diurnal corr +0.46/+0.46/+0.38. C3a -6.2%/-1.2%/+2.6% vs the keeper's registered -10.4%/-8.6%/-4.4%, with REAL mechanistic HQ_import zonal separation (-$1.7 to -$3.9 vs mainland) replacing the non-reproducible WIP effect retired in the neiso-50 keeper swap. C1 12/12; C3c/C5b carry the keeper's same ledgered gaps (unattested here - probe). Attribution (see neiso52 HEAD baseline): most of the gain vs the keeper's registered numbers is main drift (use_plant_emission_rates_v2 default flip: -10.4/-8.6/-4.4 -> -6.1/-4.1/+0.5); the measured-ladder priced node itself adds -0.2/+2.9/+2.1 points on top (2024 clearly better, 2025 slight overshoot) plus the structural gains.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-51-priced-ix.js", "id": "2026-07-06-neiso-51-priced-ix", "iso": "NEISO", "label": "neiso 51 priced ix", "shorthand": "neiso-51-priced-ix", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE / re-gate baseline) HEAD re-solve of the 2026-07-06-neiso-50-head-repro keeper recipe (measured-schedule interchange, floors on) at 2026-07-06 main (46fb645 + measured seam-ladder recal, which is inert under priced_interchange=False). Isolates main drift since the keeper's solve commit dd85d5a from the neiso-51 priced-interchange ladder effect: the sole material config drift is the use_plant_emission_rates_v2 default flip (False->True, 2026-07-06), which alone moves C3a -10.4/-8.6/-4.4% -> -6.1/-4.1/+0.5% (2023/24/25). Against this baseline the neiso-51 measured-ladder priced node adds -0.2/+2.9/+2.1 points (2024 -4.1 -> -1.2 improves; 2025 +0.5 -> +2.6 overshoots slightly) plus the structural gains (real HQ_import zonal separation, forward-mechanism P9 validation). The keeper's registered numbers are stale vs HEAD; this run is the honest comparison cell for any promotion decision.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-52-head-baseline.js", "id": "2026-07-06-neiso-52-head-baseline", "iso": "NEISO", "label": "neiso 52 head baseline", "shorthand": "neiso-52-head-baseline", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE, NEGATIVE \u2014 keeper stays neiso-48) Winter-fuel Component A (oil-inventory budget) + Component B (winter fuel-security must-run: COAL/COAL_BIT/ST_GAS floored at 0.40 min-stable on Nov-Mar cold days, TMIN < -7 C NERC onset, WRP/IEP/OFSA posture) + use_plant_emission_rates_v2 (RGGI ride-along, emissions-co2-rate-plan 9.6). Single-delta A/B on neiso-48. RESULT: the winter-fuel caveats DO NOT close. COAL 0.062/0.126/0.218 TWh vs actual 0.181/0.238/0.271 (keeper 0.058/0.113/0.234) \u2014 barely moved because the ~105 MW NEISO coal fleet already runs above min-stable on cold days economically, so the commitment floor is non-binding (D-2 coal forced ~0). C3c tail unchanged 0 h >$300 all years (actual 15/8/20): Component A's inventory budget still never binds (oil 0.35/0.23/1.54 TWh unchanged \u2014 the fuel-secure fleet already burns on cold days, so B adds no incremental oil draw). C5b storage 0.91 TWh 2025 (not improved). RULE 20 PASSES: winter_fuelsec forced share ST_GAS 0.274/0/0, coal ~0 (D-2 PASS, D-4 PASS); D-1 ST_GAS shape still FAIL (pre-existing). use_plant_emission_rates_v2 is DISPATCH-INERT for NEISO \u2014 byte-identical to the v2-off twin on price/fuel/storage/CO2. Structurally faithful (rule-19 reconcile of the disabled COAL/ST_GAS tmin limbs; no residual tuning) but low-impact: REFUTES the plan hypothesis that the winter must-run is the missing mechanism behind C1/C3c/C5b. Real root cause = fleet-capacity/availability (small coal+steam fleet) + scarcity-price formation, not a missing winter commitment. Not a keeper (rule 1: kept in code default-off, not promoted).", "file": "frontend/data/backcast/runs/2026-07-06-neiso-wfuelsec-ab-v2.js", "id": "2026-07-06-neiso-wfuelsec-ab-v2", "iso": "NEISO", "label": "neiso wfuelsec ab v2", "shorthand": "neiso-wfuelsec-ab-v2", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(PROBE, v2-OFF ATTRIBUTION TWIN of neiso-wfuelsec-ab-v2) Winter-fuel Component A + Component B enabled, use_plant_emission_rates_v2 OFF. Isolates the winter-fuel mechanism from the v2 flip per emissions-co2-rate-plan 9.6. RESULT: byte-identical to the v2-on probe on price (dwLMP 31.97/36.08/62.88), fuel mix (COAL 0.062/0.126/0.218, oil 0.35/0.23/1.54 TWh), storage (0.75/0.71/0.91 TWh) and CO2 \u2014 proving use_plant_emission_rates_v2 is fully dispatch-inert for the NEISO backcast (the measured RGGI carbon price times the v2 per-plant rate delta shifts no merit order and moves no scored metric). Confirms the winter-fuel caveats (C1 coal, C3c tail, C5b storage) are unmoved by A+B regardless of the rate basis; keeper stays neiso-48.", "file": "frontend/data/backcast/runs/2026-07-06-neiso-wfuelsec-ab-v2off.js", "id": "2026-07-06-neiso-wfuelsec-ab-v2off", "iso": "NEISO", "label": "neiso wfuelsec ab v2off", "shorthand": "neiso-wfuelsec-ab-v2off", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-06-nyiso-53-li-tsl-ablation", "date": "2026-07-06", "definition": "G-05 forced-energy determination applied 2026-07-07 (keeper unchanged; NO model change). The rule-20 C8 forced-energy breaches on ST_GAS (60.8/69.8/59.7%) and CT_PEAKER (76.2/70.1/39.4%, immaterial/C8-skipped) are adjudicated LEGITIMATE reliability commitments (keep+disclose, caiso-58 precedent). ST_GAS = downstate NYC/LI steamers' genuine persistent 24h base (measured overnight CF 0.11-0.17, online 100% of year; D-1 shape r 0.94). CT_PEAKER binds entirely in its HB14-21 ramp (D-4 off-window 0.0% after correcting the diagnostic window to [14,22)). Confirmed byte-identical at HEAD (re-solve reproduced dispatch exactly). Determination NOT-YET (disclosed hard breach, rule-1 faithfulness). Evidence: docs/handoffs/g05-forced-energy-caiso-ct-nyiso-stgas-2026-07.md. --- L-11 probe: nyiso-52 recipe + Zone-K LCR/TSL import cap (nyiso_li_lcr_tsl, issue #1345 \u2014 replaces the LI 0.45 self-supply floor; published locality import limit, HB14-21 window) + use_plant_emission_rates_v2=True (\u00a79.6 ride-along).", "file": "frontend/data/backcast/runs/2026-07-06-nyiso-53-li-tsl.js", "id": "2026-07-06-nyiso-53-li-tsl", "iso": "NYISO", "label": "nyiso 53 li tsl", "market_story": "ST_GAS +2.7/+3.8/+3.9 TWh and CT_PEAKER +1.1/+0.9/+0.6 TWh vs the zero-forcing twin, displacing CC (-2.3/-3.1/-3.0): NYISO really does commit its downstate steam and peaker fleet out of merit for local reliability (DARU/SRE commitments, steamer minimum-run blocks, the PR-#1442 CAMPD-derived temperature windows) \u2014 behaviour a pure-ED LP cannot produce. Even WITH the floors both classes still under-run the measured actuals (ST_GAS 7.2/8.1/10.3 vs 8.7/11.1/16.0; CT_PEAKER 1.3/1.4/2.4 vs 2.3/2.1/2.8 TWh), so the floors move dispatch toward measured, never past it; the remaining gap is the #1344 reserve-scarcity commitment frontier (data-blocked, Ask-B). The former nyiso_local_selfsupply floor contributes nothing here \u2014 the Zone-K TSL import cap replaced it (issue #1345) and LI energy clears economically.", "shorthand": "nyiso-53-li-tsl", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "(ABLATION TWIN of 2026-07-06-nyiso-53-li-tsl) D-3 zero-forcing twin (rule 21): the keeper recipe verbatim with all merchant floors/bridges zero-forced (protected set only: nuclear must-run, CHP steam, coal take-or-pay). The keeper-vs-twin per-class delta shows what each remaining floor buys.", "file": "frontend/data/backcast/runs/2026-07-06-nyiso-53-li-tsl-ablation.js", "id": "2026-07-06-nyiso-53-li-tsl-ablation", "iso": "NYISO", "label": "nyiso 53 li-tsl (ABLATION TWIN)", "shorthand": "nyiso-53-li-tsl-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "L-11 probe: nyiso-52 recipe + Zone-K LCR/TSL import cap (nyiso_li_lcr_tsl, issue #1345 \u2014 replaces the LI 0.45 self-supply floor; published locality import limit, HB14-21 window) ; v2 OFF (the \u00a79.6 ablation-resolve twin isolating the v2 flip's contribution).", "file": "frontend/data/backcast/runs/2026-07-06-nyiso53-v2off-twin.js", "id": "2026-07-06-nyiso53-v2off-twin", "iso": "NYISO", "label": "nyiso53 v2off twin", "shorthand": "nyiso53-v2off-twin", "years": [2023, 2024, 2025]}, {"date": "2026-07-06", "definition": "KEEPER (promoted 2026-07-06, replacing pjm-77; L-13 lane). Two grounded structural changes on the pjm-77 recipe: (1) G-21 SRMC re-grounding \u2014 the two sub-SRMC residual offer artifacts ST_GAS (committed/econ_low/econ_high 0.4752/0.6552/0.90) and CT_INTERMEDIATE (committed/econ_low 0.9/0.92) move to the Manual-15 composite-cost floor 1.00x. Correct offer physics (rule 1: a non-CHP steam/CT unit's part-load IHR exceeds full-load, so no tranche may clear below 1.0x AHR x delivered fuel \u2014 the floor CC_REGULAR already carries); a sub-SRMC offer is not real and is NOT kept just because it flattered gas volume. (2) CT_CHP EMAAC/Central_PA reliability tmax limbs scrubbed \u2014 all-24h flat floors binding 70.8% off-window (the deciding pjm-77 D-4 failure, 0.0052/0.0095/0.009 TWh); the class's hot-day lift is an all-hours steam-host intensification owned by chp_steam (rule 19). Scrub locked by tests/test_reliability_floor.py::TestPjmCtChpScrubLocked (rule 26). The ct_netload_drag window [15,22) is UNCHANGED: the L-13 overnight-reliability evidence check (diag_pjm_ct_overnight_evidence.py; docs/handoffs/pjm-ct-overnight-evidence-2026-07.md) confirmed overnight CT CF is a flat ~2% net-load-insensitive economic baseline (not reliability) plus a small extreme-net-load uptick 3-5x weaker than the ramp relationship \u2014 widening the hinge overnight would over-floor 2-3x; the extreme-net-load overnight duty is owned by reserve/ORDC (G-20 Phase 2, memory-gated). PROMOTED ON STRUCTURE (rule 1: keeper = most structurally faithful, not lowest MAE). Legitimacy improves vs pjm-77: D-4 CT_CHP failure RESOLVED (only residual is reliability_floor x CT_PEAKER 0.0002 TWh in 2023, a mixed-fuel-plant class-aggregation artifact \u2014 solve floors carry ZERO CT_PEAKER reliability, the drag owns the class and is 0% off-window); D-2 PASS at rubric v2.1 (CT_PEAKER 9.2/14.5/10.2% < 15% peaker budget). Determination NOT-YET (same class as pjm-77). DISCLOSED CALIBRATION TRADEOFF (rule 14, tracked as issue #1483, NOT a reason to revert): de-flooding ST_GAS relocates ~14 TWh/yr \u2014 2023 CC_REGULAR IMPROVES (-19.8 to -9.9 TWh) but 2024 CC over-runs (+13.5 TWh) and 2025 coal +6.2% (a new C2 sysvol FAIL vs pjm-77); real ST_GAS runs far more than a pure-efficiency merit order clears, an unmodeled RMR/local-deliverability driver. Price mean/tail and CT under-dispatch unchanged (the memory-blocked per-gen reserve/ORDC item, G-20 Phase 2). Zero-forcing ablation twin registered (2026-07-06-pjm-83-reground-ablation): all merchant floors to 0, CT_PEAKER total barely moves (drag does timing/shape, not net volume). See docs/calibration-log.md and docs/handoffs/pjm-ct-overnight-evidence-2026-07.md.", "file": "frontend/data/backcast/runs/2026-07-06-pjm-83-srmc-reground.js", "id": "2026-07-06-pjm-83-srmc-reground", "iso": "PJM", "label": "pjm 83 srmc reground", "shorthand": "pjm-83-srmc-reground", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-15 scarcity-tail candidate \u2014 REJECTED as the drag's second half; also the G-20a settlement-basis vehicle and the caiso-62 A/B base arm). Byte-faithful caiso-60 keeper replay at HEAD (drag ON, RA must-offer P1-native, P1-scored; LP identical to the keeper recipe \u2014 caiso_scarcity_pricing is post-solve-only in a backcast, and the recorded dirty diff is the default-off #1492 reserve code, inert here with the co-opt off and modules imported pre-edit). Carries the derived scarcity.parquet (derive_caiso_scarcity_overlay.py: VOLL $2,000 Tariff \u00a739.6.1, MCL 1,400 MW Diablo MSSC, \u03c3 2,500 MW FRP \u2014 published params, zero fitted) so C3c scores the SETTLEMENT price (G-20a owner-approved basis). RESULT \u2014 the published LOLP overlay is INERT exactly where the tail deficit is: 2024 adder mean $0.04 (0 h >$100, tail 0 h vs 52 h DA), 2025 mean $0.01 (0 h, 0 vs 8 DA small-count PASS), and ADDITIVE only to 2023's evening-merit-owned over-tail (mean $0.54, 10 h >$100; settlement 511 h vs energy-only 502 h vs 41 h DA / 21 h RT). Confirms G-20d: the CAISO tail miss is evening-merit / seam-shape, not reserve scarcity \u2014 see FINDING-caiso-seam-diurnal-2026-07-07.md (midday/evening/overnight seam misshape vs measured EIA-930: model near-flat 2.4-5.1 GW vs actual 5:1 swing; evening +2-3.2 GW over-import suppresses the premium the drag must then carry). Overlay mechanism stays built + default-off (rule 1); keeper stays caiso-60.", "file": "frontend/data/backcast/runs/2026-07-07-caiso-61-lolp-tail.js", "id": "2026-07-07-caiso-61-lolp-tail", "iso": "CAISO", "label": "caiso 61 lolp tail", "shorthand": "caiso-61-lolp-tail", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (#1492 reserve co-opt COMPLETED \u2014 participation model per the issue's own design constraints 2/3; fully inert, kept default-off per rule 1; keeper stays caiso-60). The caiso-60 keeper recipe + energy_reserve_coopt + caiso_reserve_coopt with the extension this branch adds: STORAGE backs the co-drawn spin/non-spin requirement through duration-gated RS[c,z] columns on the pergen path (power competition vs its own charge/discharge + the published 30-min ASSOC state-of-charge sustain, CAISO_AS_SUSTAIN_DURATION_H=0.5 h, Tariff AS certification), and HYDRO joins the CAISO-local pergen pool (166 plants; CAISO_HYDRO_RAMP10_FRAC=1.0 backfill, WWSIS-2 class physics) \u2014 1,249 eligible units, 14 (zone,fuel) pools, \u03a3 19.2 GW deliverable ramp vs a ~2.24 GW BAL-002-WECC-3 requirement (max(MSSC, 6% load), half/half; \u00a727.1.2.3.5 demand curves; zero fitted breakpoints). RESULT vs the caiso-61 base arm at the same HEAD: reserve price fired 0 h in ALL years (caiso-59's thermal-only build fired ~100 h 2023 up to $800 \u2014 completing the real provider set removed even those), mean \u03bb unchanged \u00b1$0.00, C3c tail unchanged. This is the pre-registered honest direction (issue #1492: participation ADDS supply; the thermal-only pool over-stated scarcity; real CAISO AS prices are ~$0 in most hours). Confirms the G-20 Layer-2 unifying root cause: the perfect-foresight LP is never reserve-tight, so no correctly-parameterized reserve mechanism can source the 2024/25 tail. Residual #1492 scope: Regulation Up/Down (no forward-derivable requirement series).", "file": "frontend/data/backcast/runs/2026-07-07-caiso-62-coopt-full.js", "id": "2026-07-07-caiso-62-coopt-full", "iso": "CAISO", "label": "caiso 62 coopt full", "shorthand": "caiso-62-coopt-full", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-61 path (b) \u2014 startup-aware RA-bridge run detection; keeper stays caiso-60, adoption = owner decision). The caiso-60 keeper recipe + caiso_ra_bridge_startup_aware: a base-cost P0 run anchors a bridge only when COMMITMENT-REAL under the unit's own start economics (run margin per MW of capacity >= the published class startup cost) \u2014 the phantom micro-runs the startup-free P0 manufactures stop chopping the solar belly into sub-min-down gaps that floored unconditionally. Zero fitted parameters (P0 economics + NREL/CAMPD-bin startup costs; rules 13/17). RESULT vs the caiso-61 base arm: RA-bridge forced energy drops ~40% (4.04/4.01/3.48 -> 2.56/2.33/2.38 TWh; peak simultaneous floor 2,483/2,820/2,629 -> 2,378/2,364/1,917 MW) \u2014 1.5-1.7 TWh/yr of belly min-load holds were phantom-anchored. The freed CC largely re-dispatches on merit (class -0.5 TWh), CT evening is UNCHANGED (712/636/449 -> 713/636/450 MW \u2014 the drag owns CT; cheap CC returns on merit), and the body prices rise slightly (mean lambda +$0.45/+0.46/+0.30, midday +$0.50-0.93 \u2014 the phantom floors were price-suppressing; 2023 tail 502->530 h). Structure-first tradeoff (rule 1): strictly more faithful UC physics and a ~40% smaller C8/D-2 forcing budget for the RA bridge, at a small honest C3a cost in an already-overpriced body whose root cause is the WECC seam shape (FINDING-caiso-seam-diurnal-2026-07-07). G-61a context: the quantity gate proved a measured no-op (bridged fleet 13.7-13.8 GW < published 19.1/15.6/15.6 GW), so detection realism \u2014 this probe \u2014 is the live G-61 lever.", "file": "frontend/data/backcast/runs/2026-07-07-caiso-63-g61b-startup.js", "id": "2026-07-07-caiso-63-g61b-startup", "iso": "CAISO", "label": "caiso 63 g61b startup", "shorthand": "caiso-63-g61b-startup", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PROBE (G-61 path (c) \u2014 curtailed-VRE-volume release; MEASURED FULLY INERT, kept default-off per rule 1; keeper stays caiso-60). The caiso-60 keeper recipe + caiso_ra_bridge_curtailment_release: a bridge gap containing an hour of genuine P0 renewable curtailment (wind+solar dispatched below available potential, 1 MW float-noise guard) never floors \u2014 the volume form of the D-8 closure \u00a77 price-based release (which was correct in isolation but inert because the midday LMP never reaches the curtailment floor). RESULT vs the caiso-61 base arm: BYTE-IDENTICAL floors, dispatch and prices in all three years \u2014 the base-cost P0 never curtails a single MWh of wind/solar in any hour of 2023-2025, so the release condition never fires. This is the pre-registered expectation (FINDING-caiso-seam-diurnal-2026-07-07: the WECC seam under-imports midday by 1-1.8 GW, keeping the model gas-marginal through the belly and starving every curtailment-based signal). The mechanism is real market design (CAISO decommits RA units in oversupply rather than curtail more VRE) and stays built for the day the seam-shape fix lands; its inertness is itself the measured coupling evidence for G-61 <- seam (G-15 residual).", "file": "frontend/data/backcast/runs/2026-07-07-caiso-64-g61c-curtail.js", "id": "2026-07-07-caiso-64-g61c-curtail", "iso": "CAISO", "label": "caiso 64 g61c curtail", "shorthand": "caiso-64-g61c-curtail", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "D-3 zero-forcing ablation TWIN of caiso65_seam_envelope_clock (rule 21): the same envelope-clock-corrected caiso-60 recipe with every merchant floor/bridge neutralized (ScenarioConfig.as_zero_forcing_ablation). ablation_of: caiso65_seam_envelope_clock (recorded here; the replay path does not thread the run_config field - see the W3a PR).", "file": "frontend/data/backcast/runs/2026-07-07-caiso65-seam-envclock-ablation.js", "id": "2026-07-07-caiso65-seam-envclock-ablation", "iso": "CAISO", "label": "caiso65 seam envclock ablation", "shorthand": "caiso65-seam-envclock-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-caiso65-seam-envclock-ablation", "date": "2026-07-07", "definition": "KEEPER (promoted 2026-07-07, owner decision; supersedes caiso-60 - same recipe, corrected envelope clock). The caiso-60 keeper recipe re-solved with the measured (month x hod) p95 corridor envelope bucketed on the MODEL clock: the CISO per-DIBA parquet's local_time stamps lag the model frame by a measured 1h (standard) / 2h (daylight) - lag-scan corr 0.972/0.961 at -1/-2h vs <=0.930 elsewhere, absolute frame anchored by January solar astronomy + the 2024-04-08 eclipse dip - so the keeper's envelope reached the LP 1-2h late. Fixed at the read seam (eia_loader._caiso_interchange_model_clock, pinned measured constants + drift guard scripts/validate_caiso_seam_hod_frame.py; zero fitted parameters, rule 23). A/B vs the caiso-61 base arm at the same code state: hod-mean corridor-flow error improves every year (mean |delta| 1402->1362 / 1803->1692 / 1979->1816 MW, gains at the phase edges h9/h18), lambda a near-wash (+-$0.0-0.8) as pre-registered; kept on correctness (rule 14). Part of the W3a forensics that WITHDREW the seam-diurnal FINDING attribution (its actual-flow table was UTC-bucketed) and reattributed the C3a body to belly gas commitment - see FINDING-caiso-seam-tz-correction-2026-07-07.md. Promotion disclosures: determination stays NOT-YET, unchanged from caiso-60. Of the 12 C-gates, 11 are unchanged and one moves: C2 system volume FAIL->CAVEAT (commercial-band), lifting the grade summary from scored 9/target 2/commercial 0/fails 7 (caiso-60) to commercial 1/fails 6 (caiso-65) - a real one-criterion gain from the corrected envelope, not identical to the caiso-60 lineage. C1 free-class 7/8->6/8 - 2023 CC_REGULAR crosses the band edge as the corrected envelope trims ~0.3-0.5 GW of phantom morning imports that backfill mostly with CC (fix-real: CI/local dispatch byte-identical across highspy 1.15.1/1.14.0, so not solver drift). C8 CT_PEAKER FAIL inherited from the caiso-58/60 lineage (owner-held per the G-11 decision). C6 stays UNATTESTED, inherited unchanged from caiso-60: calibration_attestation.json carries the caiso-60 DOF ledger plus the two new measured clock-lag constants, but the attestation still has no governance block. Ablation twin: 2026-07-07-caiso65-seam-envclock-ablation.", "file": "frontend/data/backcast/runs/2026-07-07-caiso65-seam-envelope-clock.js", "id": "2026-07-07-caiso65-seam-envelope-clock", "iso": "CAISO", "label": "caiso65 seam envelope clock", "shorthand": "caiso65-seam-envelope-clock", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-miso-45-cc-capacity) miso-45 zero-forcing ablation: identical recipe (incl. the CC demonstrated-capacity cap) with every merchant floor/bridge OFF. Keeper-minus-twin per-class deltas <=0.05 TWh (floors force <0.6 TWh; nothing floor-bought in the CC row).", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-ablation.js", "id": "2026-07-07-miso-45-ablation", "iso": "MISO", "label": "miso 45 ablation", "shorthand": "miso-45-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-miso-45-ablation", "date": "2026-07-07", "definition": "miso-45 (G-23 root-cause fix): miso-44 recipe + cc_capacity_reconcile with the MISO demonstrated-capacity cap table (derive_cc_capacity_reconcile.py --iso MISO --mode cap). Root cause of the CC_REGULAR +20 TWh overrun: EIA-860 reports 7 MISO CC plants' steam (CA) rows with BLOCK-level Summer Capacity while nameplate stays component-level; the loader's summer-preferred pmax double-counts the CTs (-2,714 MW phantom, 6 of 7 plants MISO-South, e.g. Union Power 3,457 MW modeled vs 2,428 nameplate / 2,318 CAMPD p99.9 / 2,354 EIA-860 winter). Cap = plant's own measured CAMPD p99.9 sustained peak - zero new DOF. RESULT vs miso-44: CC_REGULAR +20.0/+19.1/+3.1 -> +6.7/+7.2/-7.3 TWh; ST_GAS -8.5/-11.0/-10.5 -> -2.0/-4.6/-6.1; C1 12/16 -> 15/16 (free 8/12 -> 11/12); C3b PASS. 2025 residual moves onto the open import-starvation + coal-sigmoid rows (audit boxes 3-4). Full audit: docs/multi-iso/miso-cc-overrun-rootcause-2026-07.md. Determination stays NOT-YET (same class as miso-44): four load-bearing/supporting FAILs remain open \u2014 C1 2024 ST_GAS -9.87 TWh; C2 2025 gas -10.8% / coal +16.8%; C3a 2025 mean LMP -10.5%; C3c 2024/2025 scarcity-tail hours model 0h vs DA actual 24h/38h \u2014 plus a C5a CO2 CAVEAT (commercial-band, 2025 +7.1%) and C5b/C5c storage CAVEATs (ledgered: MISO's EIA-930 series carries no pumped-storage breakout, so the model's PS+battery discharge is scored against a battery-only actual). The promotion is on the CC-capacity root-cause fix and DOF reduction, not on these FAILs or caveats closing.", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-cc-capacity.js", "id": "2026-07-07-miso-45-cc-capacity", "iso": "MISO", "label": "miso 45 cc capacity", "market_story": "Floors force <0.6 TWh total (all four enabled MISO limbs are design-day commitment floors: hot-day coal/CT/ST_GAS units are online before the peak because operators commit against the design cooling/heating day, not the price of the hour). The miso-45 keeper-vs-twin per-class deltas are near-zero by construction - the run's structural content is the measured demonstrated-capacity cap, which is in BOTH twins; nothing in the CC row is floor-bought.", "shorthand": "miso-45-cc-capacity", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ATTRIBUTION ARM for 2026-07-07-miso-46-seam-ladder; ercot36 pattern, not a keeper) miso-45 keeper recipe replayed byte-faithfully at HEAD with NO config delta - isolates main's merged drift since the keeper SHA 86601ce (chiefly the owner-directed cc_duct_peaking all-ISO default extension 7358028) from the miso-46 measured-seam-ladder single delta. RESULT: (a) HEAD drift alone (this arm vs miso-45-committed): net interchange 35.1->36.0/15.5->16.0/3.4->4.0 TWh, 2023 COAL_PRB 122.1->122.8 (+0.7 - the duct drift is what pushes the pre-existing +7.4 overrun to the +8.34 C1 band edge, NOT the ladder); (b) the LADDER single delta (miso-46 vs this arm): 2023 near-no-op (net 36.0->35.2, PRB +0.1), 2024 net +3.6 (16.0->19.6; PRB -1.9, CT -0.7, ST_GAS -0.6), 2025 net +9.2 (4.0->13.2; CT -2.6, CC -2.2, PRB -1.8, ST_GAS -1.2, BIT -1.0) - the 2025 restored imports displace gas ~2:1 over coal, confirming the coal-sigmoid re-attribution (#1347). Unattested by design (attribution probe, not a keeper candidate).", "file": "frontend/data/backcast/runs/2026-07-07-miso-45-head-replay.js", "id": "2026-07-07-miso-45-head-replay", "iso": "MISO", "label": "miso 45 head replay", "shorthand": "miso-45-head-replay", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-miso-46-seam-ladder) miso-46 zero-forcing ablation: identical recipe (incl. the measured seam ladders + cc capacity cap) with every merchant floor OFF (reliability_floor=false, the MISO zero-forcing delta; run_config carries a post_hoc recording-fidelity correction - the solve is proven floor-off: no floor log line + nonzero deltas where same-config replays are byte-identical). Keeper-minus-twin per-class deltas <=0.06 TWh (2023 COAL_BIT 0.06 is the max; floors force <0.6 TWh; nothing in the import/coal story is floor-bought).", "file": "frontend/data/backcast/runs/2026-07-07-miso-46-ablation.js", "id": "2026-07-07-miso-46-ablation", "iso": "MISO", "label": "miso 46 ablation", "shorthand": "miso-46-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-miso-46-ablation", "date": "2026-07-07", "definition": "miso-46 (G-23 residual root-cause fix): miso-45 keeper recipe + miso_seam_measured_ladder at HEAD (single --set delta via replay_keeper; HEAD also carries the owner-directed cc_duct_peaking default extension 7358028, in ANY new run). Root cause (docs/multi-iso/miso-import-starvation-rootcause-2026-07.md): the measured PJM+IESO seam is a firm/scheduled base - imports in 97.5-99.5% of ALL hours, hourly flow uncorrelated with the RT spread (r=+0.06), 2025 mean RT spread $0.00 while 28 TWh flowed, 46-56% of import MWh inside the $2 hurdle - which hurdle-gated spot-spread pricing structurally deletes in a zero-spread year (miso-45 2025: 3.4 TWh gross imports vs 19.0 actual net, displaced onto +22 TWh PRB - the C2 FAIL). Fix = the NEISO audit-C-6 measured-ladder pattern on MISO's three seams (interchange_config.MISO_SEAM_LADDER_BY_YEAR, frozen scripts/derive_miso_seam_ladders.py: EIA-930 per-seam flow durations Q-Q coupled with the measured MISO DA hub LMP on the existing 8-band grid; zero fitted parameters, rule 23; envelopes/capacities/Manitoba unchanged; every band clears economically on the model's own hourly price - contrast the rejected miso_firm_import_floor pin). RESULT vs miso-45: net interchange +35.2/+19.6/+13.2 TWh vs actual +37.9/+23.1/+19.0 (was +35.1/+15.5/+3.4); 2025 PJM-seam imports 1.4 -> 16.7 TWh; South exports restored -5.7/-8.4. Trade-off surfaced (rule 14 - removing a compensating error): the restored imports displace GAS not PRB (model PRB undercuts even the $21.82 base rung): C2-2025 gas -10.8 -> -14.1% / coal +16.8 -> +15.7% (both FAIL), C3a -10.5 -> -11.8%, C3b PASS -> commercial caveat (NRMSE 0.168), C1 15/16 -> 14/16 (2023 COAL_PRB +7.4 -> +8.34 crosses the band edge; 2024 ST_GAS -10.05 unchanged-ish). The ~+30 TWh dear-gas coal-vs-gas mis-order re-attributes to the coal-sigmoid offer level (#1347, C-1 ledgered DOF - NOT refit, rule 23) + the 0h scarcity tail (G-20e data-blocked). DOF ledger: seam family flips residual -> measured-physical (5 entries / 3 residual at HEAD). Determination NOT-YET (same class as miso-45). Same-box replay determinism: byte-identical dispatch/system/flows on a full re-solve. Memory (G-40): VmHWM 14.85 GB yr-1 / 15.76 GB yr-2 peak; OOM-killed at 15.95 GB without swap on a 15 GiB box; completes with a 10 GiB swapfile (<=190 MB swapped). KEEPER PROMOTED 2026-07-07 (owner decision, gap-review session): structure-over-fit per rules 1/14 \u2014 the seam ladder is measured physical structure and the fit regression is the disclosed compensating-error re-attribution to #1347; pjm-83 precedent. Supersedes miso-45-cc-capacity as MISO keeper.", "file": "frontend/data/backcast/runs/2026-07-07-miso-46-seam-ladder.js", "id": "2026-07-07-miso-46-seam-ladder", "iso": "MISO", "label": "miso 46 seam ladder", "shorthand": "miso-46-seam-ladder", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "Zero-mechanism ablation twin of neiso53_winter_coldsnap_ab: all three winter-fuel mechanisms off (= neiso-50 keeper baseline), same harness/BTM basis, for D-3 attribution of the winter stack.", "file": "frontend/data/backcast/runs/2026-07-07-neiso53-winter-fuelsec-ablation.js", "id": "2026-07-07-neiso53-winter-fuelsec-ablation", "iso": "NEISO", "label": "neiso53 winter fuelsec ablation", "shorthand": "neiso53-winter-fuelsec-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-neiso53-winter-fuelsec-ablation", "date": "2026-07-07", "definition": "G-24 NEISO winter fuel-security adoption on the neiso-50 base: three real ISO-NE winter mechanisms turned on together - gas cold-snap availability derate (TDFOR) + Component A oil-inventory budget + Component B fuel-secure must-run (WRP/IEP/OFSA + NERC Winter Storm Elliott). On 2023-2025 they are DORMANT on every scored metric (C3c/C5b unmoved, prices byte-near-identical to the ablation twin): the ample NEISO winter fleet never goes reserve-short under a <=13%-on-8-hours derate and the dual-fuel oil-parity cap (~$258) holds, so Component A never binds. Component B does commit the immaterial fuel-secure COAL fleet on cold days (<0.3% ISO load, reported-not-gated, rule 20 v2.1). Adopted for FORWARD faithfulness (rule 1: real, forward-responsive structure stays in even when the backcast residual does not move; binds in colder forecast years). Same determination as neiso-50 (CALIBRATED-WITH-CAVEATS). Refutes the hypothesis that a missing winter mechanism drives the C3c/C5b residual - that is a NEISO winter capacity-adequacy / scarcity-price-formation gap.", "file": "frontend/data/backcast/runs/2026-07-07-neiso53-winter-fuelsec-coldsnap.js", "id": "2026-07-07-neiso53-winter-fuelsec-coldsnap", "iso": "NEISO", "label": "neiso53 winter fuelsec coldsnap", "market_story": "The NEISO winter fuel-security stack (cold-snap gas derate + oil-inventory budget + fuel-secure must-run) is structurally faithful but DORMANT on every scored 2023-2025 metric: vs the zero-mechanism twin, C3c stays 0h >$300 (max ~$258, oil-parity cap), 2025 storage moves 0.697->0.715 TWh (+2.6%), winter oil +0.8%, Component A oil budget never approached (~3.3 of 9.79 M MMBtu/month). Component B does commit the tiny fuel-secure COAL fleet on cold days (D-2 forced 0.35/0.23/0.02 vs 0.0 in the twin) but COAL is <0.3% of ISO load - reported-not-gated. The C3c tail / C5b storage residual is a capacity-adequacy / price-formation gap, not a fuel-security-mechanism gap - the mechanisms are kept on for the colder forecast years they would bind in, not to move this backcast.", "shorthand": "neiso53-winter-fuelsec-coldsnap", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-nyiso-55-ldc-transport-ablation", "date": "2026-07-07", "definition": "(CANDIDATE \u2014 G-13 RESOLVED; keeper stays 2026-07-06-nyiso-53-li-tsl pending owner promotion) The nyiso-53 keeper recipe with the downstate CT-peaker gas re-grounded on the CORRECT rate-class, per-zone measured delivered index (nyiso_downstate_ct_gas_daily; nyiso-downstate-gas datatype v2). The LM6000 downstate peakers are non-firm TRANSPORTATION customers, so their delivered fuel = Transco Z6 NY daily commodity + the LDC monthly non-firm transportation delivery rate (KEDNY SC-22 for NYC, KEDLI SC-19 for Long Island; National Grid statnfdr statements, fetched free from the tariff archive). This is the Ask-A LI/NYC delivered-gas intake the G-13 register row called for; it supersedes nyiso-54's statewide EIA-N3050NY3 firm-citygate stand-in with the correct rate class at the correct per-zone boundary (rules #1/#11/#12/#13), zero new free parameters. RESULT vs nyiso-53: C1 fuel-mix PASS all 14/14 classes (the CT_PEAKER over-run is NOT reintroduced), C2 PASS, C3c price-tail PASS, C5 dispatch-corr PASS, C7 shape PASS; C3a/C3b/C8 unchanged from the keeper (nyiso-53 ledgers these same values as accepted #1344/Ask-B-blocked caveats). A metrics WASH but strictly more structurally faithful: the correct delivered-fuel boundary no longer being the open root cause is the deliverable, and the residual downstate scarcity level/tail is reattributed to #1344/Ask-B (endogenous reserve-scarcity commitment), a distinct data block. NOT-YET here is solely the missing governance attestation (a keeper-promotion step), not a metrics regression.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-55-ldc-transport.js", "id": "2026-07-07-nyiso-55-ldc-transport", "iso": "NYISO", "label": "nyiso 55 ldc transport", "market_story": "Re-grounding the downstate CT gas on the correct per-zone non-firm TRANSPORTATION delivered index (Transco Z6 NY daily commodity, up to ~$100/MMBtu on Jan-2025 arctic days, + KEDNY SC-22 ~$2.5-3.4/MMBtu for NYC / KEDLI SC-19 ~$1.7-2.9/MMBtu for Long Island) lifts the peaker offer on the exact scarce days it runs and prices NYC peakers above LI ones, which is the delivered-fuel physics a pure-ED LP should honor. Vs the zero-forcing twin, the PR-#1442 windowed temperature floors still commit downstate CT_PEAKER (2023 ~88% of class energy) and ST_GAS out of merit for local reliability \u2014 behaviour a pure-ED LP cannot produce. But the correct gas boundary cannot move the >$300 tail or the mean-price level: the peakers the real market commits for reserve sit idle in the pure-ED LP (issue #1344, data-blocked on the Ask-B condition-varying reserve-requirement series), so pricing their gas correctly is a structurally-faithful refinement that leaves the masked residual where it is (rule #1). Kept honest: no offer markup, adder, or floor is tuned to close the gap (rules 13/26).", "shorthand": "nyiso-55-ldc-transport", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-nyiso-55-ldc-transport) D-3 zero-forcing ablation twin (rule 21) of the per-zone LDC-transport candidate: the candidate recipe verbatim with all merchant floors/bridges zero-forced.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-55-ldc-transport-ablation.js", "id": "2026-07-07-nyiso-55-ldc-transport-ablation", "iso": "NYISO", "label": "nyiso 55 ldc-transport (ABLATION TWIN)", "shorthand": "nyiso-55-ldc-transport-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-07-nyiso-56-measured-zonal-ablation", "date": "2026-07-07", "definition": "G-20c KEEPER (promoted 2026-07-07, owner: 'if it's better promote it'; supersedes nyiso-53-li-tsl). Determination CALIBRATED-WITH-CAVEATS. nyiso-53 recipe VERBATIM (nyiso_li_lcr_tsl #1345 + use_plant_emission_rates_v2 + downstate CT gas basis + energy_reserve_coopt) with ONE change: the LP now dispatches on MEASURED per-zone hourly load shapes instead of the static Gold-Book shares. load_zonal_shares gained a raw-file fallback (eia_loader) so the measured NYISO 'pal' actual-load (data/raw/zone-specific-demand/NYISO, upload U3) drives every zone's own diurnal/seasonal shape even when the gitignored data/clean parquet is absent \u2014 rule-12 measured>estimate, forward-reproducible, no new free parameter. Static shares understated the downstate peak (NYC 0.28 static vs 0.34 measured at peak; LI 0.12 vs 0.17) and forced every zone to peak the same hour, so the import-constrained NYC/SENY pocket never tightened. RESULT (G-20c): with measured load the downstate pocket BINDS and the in-LP locational reserve co-opt fires \u2014 2023 NYC/Hudson LBMP spikes to $1,684 while Upstate maxes at $152 (genuinely locational). C3c tail vs RT actual: 2023 21h vs 10h (was 0h), 2025 14h vs 42h; C3a mean 2023 +1.6% vs DA (was -9.0%), C3b NRMSE 0.188/0.200/0.165 (keeper 0.182/0.221/0.190); C1/C2/C4 PASS, C7 PASS, no load-bearing regression. OPEN: 2024 (mild year) + 2025 deep >$300 tail still under \u2014 next lever is downstate import discipline (measured NYC locality import limit 2,875 MW < model Dunwoodie 3,900 MW estimate, apply in-window like #1345). C3c FAILs the DA-expressible gate (DA actual 1h) = the G-20a scoring-basis artifact, not an RT over-fire. C8 ST_GAS breach is the keeper's owner-held-legitimate G-05 item at LOWER forced share (30/45/38% vs keeper 61/70/60%) \u2014 kept+disclosed in the attestation. Governance ATTESTED; registered zero-forcing ablation twin. It dominates nyiso-53 on measured faithfulness (rule 12) + C3a/C3b with no load-bearing regression. || 2026-07-09: C8 ST_GAS protective caveat CLEARED \u2014 grounded under rubric v2.2 (GROUNDED ABOVE BUDGET, clean PASS all years). D4_WINDOWS[(reliability_floor, ST_GAS)] = (0,24) declared with the G-05 measured evidence; diagnostics regenerated at HEAD (CHP re-class refreshed the D-2 denominators: ST_GAS 36.4/53.8/44.8% forced of 8.0/8.6/10.6 TWh class). The all-hours gas_st_netload_drag (ERCOT-46/PJM-94 mechanism) was re-adjudicated for NYISO and rejected on its own honesty gates (derive_nyiso_st_gas_netload_drag.py \u2014 downstate base is unconditional local-reliability commitment, not net-load-hinged). No re-solve; keeper unchanged. Remaining caveats: ledgered C3c (DA-expressible tail, #1344 data-blocked) + commercial-band C5a CO2 2024.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-56-measured-zonal.js", "id": "2026-07-07-nyiso-56-measured-zonal", "iso": "NYISO", "label": "nyiso 56 measured zonal", "market_story": "The keeper vs its zero-forcing twin isolates what the measured load shares buy on top of the merchant floors. The one change from nyiso-53 is a measured-data source swap (static Gold-Book -> measured per-zone hourly load shapes), which adds no floor and no free parameter, so the twin delta is dominated by the same PR-#1442 windowed downstate temperature ramps the nyiso-53 twin already characterised. What the measured shares change is WHERE the load sits: putting the true ~34% NYC / ~17% LI peak share into the LP (vs the flat 0.28/0.12 static) tightens the import-constrained NYC/SENY pocket, so the in-LP locational reserve co-opt fires and the downstate LBMP tail forms ($1,684/MWh in 2023, Upstate flat at $152) - real locational scarcity a NYCA-aggregate load allocation cannot produce, and it also LOWERS ST_GAS floor-forcing (30/45/38% vs 61/70/60%) because more of the downstate steam base now clears economically under the correct local load.", "shorthand": "nyiso-56-measured-zonal", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(ABLATION TWIN of 2026-07-07-nyiso-56-measured-zonal) D-3 zero-forcing ablation twin of 2026-07-07-nyiso-56-measured-zonal (rule 21): the nyiso-56 recipe verbatim (measured per-zone load shares, G-20c) with all merchant floors/bridges zero-forced.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-56-measured-zonal-ablation.js", "id": "2026-07-07-nyiso-56-measured-zonal-ablation", "iso": "NYISO", "label": "nyiso 56 measured zonal (ABLATION TWIN)", "shorthand": "nyiso-56-measured-zonal-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "G-20c: main measured-zonal recipe + primary-source-corrected NYISO_RCPF_LOCATIONAL (SOM 2023-25 p297: East 10-min $775, SENY 1300 MW, NYC $25) in the live energy_reserve_coopt path. Single-delta A/B vs nyiso-56-measured-zonal.", "file": "frontend/data/backcast/runs/2026-07-07-nyiso-57-locational-rcpf.js", "id": "2026-07-07-nyiso-57-locational-rcpf", "iso": "NYISO", "label": "nyiso 57 locational rcpf", "shorthand": "nyiso-57-locational-rcpf", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "PJM 86 pjm-83 keeper recipe VERBATIM re-solved at HEAD: the flag-off baseline of the pjm-87 per-gen opportunity-cost A/B, on the same data tree as the treatment (regenerated clean partitions + the per-BA EIA-930 PJM demand rewire: 1-2h clock lag fixed, 2023/2024 zero-hour gaps replaced with real meter data, the 2024 interpolation-shaved ~104 GW ridge restored). No mechanism deltas vs pjm-83 \u2014 any move vs the committed pjm-83 bundle is the data tree.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-86-pjm83-head.js", "id": "2026-07-07-pjm-86-pjm83-head", "iso": "PJM", "label": "pjm 86 pjm83 head", "shorthand": "pjm-86-pjm83-head", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(PROBE \u2014 keeper decision pending the pjm-86 same-tree A/B) PJM 87 per-gen OPPORTUNITY-COST reserve co-opt (G-20b successor): pjm-83 keeper recipe VERBATIM (= the pjm-86 same-tree baseline) + pjm_reserve_pergen ((zone, fuel-class) pooled R<=ramp10 co-opt, measured RTO+MAD Primary families) + pjm_reserve_pergen_sync (NEW: measured Synchronized sub-product families sr_req_mw/mad_sr_req_mw on the published Synchronized ORDC rows; per-pool SYNC/NON-SYNC column split sharing the joint P+R row \u2014 sync servable only by ONLINE 10-min ramp, scoped at the P0->P1 seam from the P0 run pattern; offline fast-start ramp serves non-sync Primary per Manual 11 sec 4.2; energy availability NOT masked so P1 redispatch prices the opportunity cost) + measured_ramp_capability (rule 14). Fixes pjm-81's non-fire (joint headroom let idle capacity back reserve; 1 fired hour / 3 yr) by composing per-gen ramp limits WITH online scoping. RESULT: reserve dual > 0 in 133/44/50 hours (2023/24/25, mostly afternoon 11-18h) \u2014 the first PJM reserve scoping to fire nontrivially (vs pjm-81's 1h/3yr). All duals stay under $32, well below the $300 penalty step (never fires the shortage regime) \u2014 correctly sub-shortage opportunity-cost, as designed. But magnitude is modest: most positive-dual hours sit in $0-10, not the targeted $10-80 band, so this only partially engages the $75-200 afternoon residual, not a residual-closing fix.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-87-pergen-oppcost.js", "id": "2026-07-07-pjm-87-pergen-oppcost", "iso": "PJM", "label": "pjm 87 pergen oppcost", "shorthand": "pjm-87-pergen-oppcost", "years": [2023, 2024, 2025]}, {"date": "2026-07-07", "definition": "(PROBE) PJM 88 size-split pergen pooling tier (pjm-87 diagnosis remedy): pjm-87 recipe VERBATIM + pjm_reserve_pergen_size_split (splits each base (zone, fuel-class) pool's plants above 2.0x the pool's own mean plant capacity into individual reserve columns -- self-normalizing threshold, no absolute MW cutoff -- 91-95 pools / 182-190 sync-split R columns vs the base 39/78; a middle ground short of the memory-infeasible full per-plant tier, 407 pools / 814 columns). Diagnosis: none of the 4 balance rows ever bind (8-14x margin at the tightest hour of 3 years); duals come from the per-pool joint headroom row, diluted by 39 uniform pools letting the LP source PJM's small requirement from any idle pool. RESULT: memory-safe (no OOM), fires ~50% more hours (205/54/70 vs pjm-87's 133/44/50) but does NOT sharpen the magnitude into the $10-80 band -- distribution shape unchanged, still >=90% in $0-10. Unlike pjm-87, introduces a real 2025-specific dispatch shift (CT_PEAKER -2.53 TWh vs pjm-87, CC_REGULAR +1.44 TWh) and a genuine #1484 CT_PEAKER D-2 drag-share movement (10.54%->11.93%, still under the 15% cap, no gate crossed). Not a promotion case -- frequency gain without magnitude gain, at a real (small) dispatch-distortion cost pjm-87 didn't have.", "file": "frontend/data/backcast/runs/2026-07-07-pjm-88-pergen-sizesplit.js", "id": "2026-07-07-pjm-88-pergen-sizesplit", "iso": "PJM", "label": "pjm 88 pergen sizesplit", "shorthand": "pjm-88-pergen-sizesplit", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "(PROBE - keeper stays caiso65-seam-envelope-clock) make-the-3-zones-real A/B: caiso65 recipe + measured PG&E/SoCal citygate zonal gas basis (mean-zero; weekly EIA NGWU prints; N-S spread -0.49/+0.54/-0.18 USD/MMBtu 2023/24/25) + WECC directional Path 15/26 ratings (15: 3265 N-S / 5400 S-N; 26: 4000 N-S / 3000 S-N). Both mechanisms bind (Path 26 N-S at its 4000 MW cap 4000-5250 h/yr; NP15/ZP26 separate for the first time) but the N-S LMP basis stays inverted (2024 basis NP15-SP15: -4.5 -> -3.3 vs actual +8.0) - the model ships ~3 GW N->S around the clock, SP15 structurally short, so the residual reattributes to the G-15 seam contracted overnight/evening base under-delivered into SP15, NOT topology or gas price. Zero fitted parameters (rules 13/14/24). D-gates inherited from caiso65 (D4 off-window PASS; D1/D2 CT fails unchanged; 2024 CT-drag forced share 65.9 -> 47.6 pct). Determination NOT-YET (governance gate unattested, as caiso65).", "file": "frontend/data/backcast/runs/2026-07-08-caiso-67-zonalgas-asympaths.js", "id": "2026-07-08-caiso-67-zonalgas-asympaths", "iso": "CAISO", "label": "caiso 67 zonalgas asympaths", "shorthand": "caiso-67-zonalgas-asympaths", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "temp-derate full-keeper main -- caiso65_seam_envelope_clock config + temp_dependent_derate, 2023-2025", "file": "frontend/data/backcast/runs/2026-07-08-caiso-68-tempderate.js", "id": "2026-07-08-caiso-68-tempderate", "iso": "CAISO", "label": "caiso 68 tempderate", "shorthand": "caiso-68-tempderate", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "temp-derate full-keeper ablation -- caiso65_seam_envelope_clock config + temp_dependent_derate, 2023-2025", "file": "frontend/data/backcast/runs/2026-07-08-caiso-68-tempderate-ablation.js", "id": "2026-07-08-caiso-68-tempderate-ablation", "iso": "CAISO", "label": "caiso 68 tempderate ablation", "shorthand": "caiso-68-tempderate-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "D-7 statistical-mode A/B twin \u2014 SAME-SHA replay of the CURRENT CAISO keeper 2026-07-07-caiso65-seam-envelope-clock (bundle caiso65_seam_envelope_clock), replayed at HEAD fab2254 with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False); structural model + realized annual Henry Hub gas price unchanged. G-10 honesty-gate twin: the D-7 gap is now same-SHA-comparable to the keeper, replacing the r2/v2-confounded caiso51 probes. Fail count 6\u21928 of 11 scored (C6 governance excluded). CAISO remains the one ISO where price LEVEL improves out-of-sample: C3a mean LMP FAIL\u2192FAIL but closer (+40.2%\u2192+29.3% / +26.2%\u2192+19.9% / +12.4%\u2192+8.1% vs DA) and C3b shape improves; the overlays instead carry the volume/CO2 side \u2014 CO2 C5a PASS\u2192FAIL (+5%\u2192+10.7%), sysvol C2 CAVEAT\u2192FAIL, fuel-mix C1 FAIL\u2192FAIL widening. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-08-caiso65-statmode.js", "id": "2026-07-08-caiso65-statmode", "iso": "CAISO", "label": "caiso65 statmode", "shorthand": "caiso65-statmode", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-ercot46-clock-steamgas-ablation", "date": "2026-07-08", "definition": "SUPERSEDED 2026-07-10 by ERCOT keeper 2026-07-10-ercot53-hsl-930fill (owner-approved promotion): ercot53 carries this ercot46 floor stack forward unchanged (plus the intervening ercot51 coal net-summer derate and ercot52 ORDC cap-dual fix) and additionally corrects a 2024 HSL measured-input data-quality bug; it strictly extends this recipe rather than replacing its mechanisms. Retained for history. Original definition: ercot46 clock+steamgas: ercot45 clock-unified + ST_GAS reliability realism - gas_st_netload_drag (frozen overnight-CF-vs-netload floor, slope 0.00906/GW intercept -0.1376 cap 0.34, docs/ercot-st-gas-netload-drag-2026-06.md) + gas_st_startup_cost (ST_GAS_COMMITMENT_PARAMS startup/min-run/min-down markup so a stop-start costs more than idling). Keeper-candidate C arm of the stepwise A/B/C; a structural mechanism change, scored LOYO within 2023-2025 before promotion (rule 22).", "file": "frontend/data/backcast/runs/2026-07-08-ercot46-clock-steamgas.js", "id": "2026-07-08-ercot46-clock-steamgas", "iso": "ERCOT", "label": "ercot46 clock steamgas", "market_story": "ST_GAS holds its overnight minimum (RUC-style reliability commitment, not economics) because dropping reliability_floor/ct_netload_drag/gas_st_netload_drag/ra_mustoffer_bridge/the WTX curtailment ceiling all at once reopens the ST_GAS under-run to -4.02/-8.69/-6.12 TWh and blows up mean LMP +117%/+163%/+52% - the real market keeps these units committed through low-price troughs for local/system reliability, not because the energy price justifies it; CT_PEAKER's evening ramp floor and the WTX West-corridor curtailment ceiling are the analogous real-market drivers for their classes, each documented with its own window/driver in legitimacy_diagnostics.json.", "shorthand": "ercot46-clock-steamgas", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "ercot46 zero-forcing ablation twin (rule 21): every merchant floor/bridge neutralized (reliability_floor, ct_netload_drag, gas_st_netload_drag, ra_mustoffer_bridge, ...) via ScenarioConfig.as_zero_forcing_ablation, on the identical clock-corrected data + ST_GAS startup-cost commitment physics as the ercot46 base. Quantifies what the floors buy vs the base keeper.", "file": "frontend/data/backcast/runs/2026-07-08-ercot46-clock-steamgas-ablation.js", "id": "2026-07-08-ercot46-clock-steamgas-ablation", "iso": "ERCOT", "label": "ercot46 clock steamgas ablation", "shorthand": "ercot46-clock-steamgas-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "D-7 statistical-mode A/B twin \u2014 SAME-SHA replay of the CURRENT ERCOT keeper 2026-07-08-ercot46-clock-steamgas (bundle ercot46_clock_steamgas), replayed at HEAD fab2254 with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False); structural model + realized annual Henry Hub gas price unchanged. G-10 honesty-gate twin: the D-7 gap is now same-SHA-comparable to the keeper. Fail count 2\u21927 of 11 scored (C6 governance excluded) \u2014 price level C3a CAVEAT\u2192FAIL (+1.7%\u2192\u221214.5%/\u221222.5%/\u221248.5% vs DA), fuel-mix C1 PASS\u2192FAIL (COAL_PRB over-run), dispatch-corr C4 PASS\u2192FAIL, CO2 C5a PASS but worsens (+2%\u2192+6%); CT/ST forced-energy share (C8) jumps to 47\u201358%. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-08-ercot46-statmode.js", "id": "2026-07-08-ercot46-statmode", "iso": "ERCOT", "label": "ercot46 statmode", "shorthand": "ercot46-statmode", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "temp-derate full-keeper ablation -- ercot46_clock_steamgas config (reconstructed from meta.json, not the curated calibration_flags subset) + temp_dependent_derate, 2023-2025 (rule 16) || REJECTED WITH CAUSE (owner decision 2026-07-09): the temp-derate line is closed for ERCOT. Cause: the fleet's own measured behaviour refutes the literature slopes \u2014 scarcity-hour (RT>$200) capability slope fitted above 34C is ~0 or negative for every gas class (CC -0.27, CT -0.04, ST_GAS -0.29, CC_CHP -1.41 %/degC vs model +0.76/+1.26/+0.54; online CT p90 = 1.00-1.02x rating in every bin 30-46C), production at TMAX>=40C reached 95-100%+ of net-summer rating for most capacity, and telemetered RTOLCAP showed 6.9-8.3 GW spare in the model's deep hours (scripts/probes/_ercot_temp_capability_envelope.py; calibration-log 2026-07-09). The measured ERCOT parameterization is slope~0 above rating = the keeper's flat net-summer treatment. Keeper stays 2026-07-08-ercot46-clock-steamgas; the thin-tail miss routes to the measured DAM offer-surface path (G-22 SS5.1 / ercot37 SS8).", "file": "frontend/data/backcast/runs/2026-07-08-ercot48-tempderate-full-ablation.js", "id": "2026-07-08-ercot48-tempderate-full-ablation", "iso": "ERCOT", "label": "ercot48 tempderate full ablation", "shorthand": "ercot48-tempderate-full-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "temp-derate full-keeper A/B (TREATMENT arm): ercot46_clock_steamgas keeper config (reconstructed from meta.json, not the curated calibration_flags subset) + temp_dependent_derate=True, all 3 train years. C3c price-tail moves toward the actual DA scarcity-hour count (2023 104h->328h vs 311h actual; 2024 29h->101h vs 68h; 2025 4h->48h vs 23h) but C3a mean-LMP and C3b price-shape blow out (+9.3%/+6.5%/+4.9% -> +269%/+161%/+42% mean-LMP error) -- the derate reshapes too many hours, not just the scarcity tail. PROBE, not a promotion. || REJECTED WITH CAUSE (owner decision 2026-07-09): the temp-derate line is closed for ERCOT. Cause: the fleet's own measured behaviour refutes the literature slopes \u2014 scarcity-hour (RT>$200) capability slope fitted above 34C is ~0 or negative for every gas class (CC -0.27, CT -0.04, ST_GAS -0.29, CC_CHP -1.41 %/degC vs model +0.76/+1.26/+0.54; online CT p90 = 1.00-1.02x rating in every bin 30-46C), production at TMAX>=40C reached 95-100%+ of net-summer rating for most capacity, and telemetered RTOLCAP showed 6.9-8.3 GW spare in the model's deep hours (scripts/probes/_ercot_temp_capability_envelope.py; calibration-log 2026-07-09). The measured ERCOT parameterization is slope~0 above rating = the keeper's flat net-summer treatment. Keeper stays 2026-07-08-ercot46-clock-steamgas; the thin-tail miss routes to the measured DAM offer-surface path (G-22 SS5.1 / ercot37 SS8).", "file": "frontend/data/backcast/runs/2026-07-08-ercot48-tempderate-full-probe.js", "id": "2026-07-08-ercot48-tempderate-full-probe", "iso": "ERCOT", "label": "ercot48 tempderate full probe", "shorthand": "ercot48-tempderate-full-probe", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "(ABLATION TWIN of 2026-07-08-miso-47-steamgas-ct) Zero-forcing reference solve: the miso-47 keeper recipe with every merchant floor/bridge/drag neutralized (reliability_floor OFF - the ST_GAS overnight + CT_PEAKER evening drag limbs removed), keeping the structural protected set (nuclear must-run, CHP steam, coal take-or-pay). Isolates what the drag limbs buy: CT_PEAKER -0.3..-0.7 TWh/yr, ST_GAS ~flat.", "file": "frontend/data/backcast/runs/2026-07-08-miso-47-steamgas-ablation.js", "id": "2026-07-08-miso-47-steamgas-ablation", "iso": "MISO", "label": "miso 47 steamgas ablation", "shorthand": "miso-47-steamgas-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-miso-47-steamgas-ablation", "date": "2026-07-08", "definition": "MISO 47 steam-gas overnight + CT evening drag keeper candidate: miso-46 seam-ladder recipe re-solved at HEAD, absorbing two base-data structural mechanisms vs miso-46 \u2014 (1) ST_GAS extreme-day overnight [0,6] drag in the reliability_floor engine (tmax/tmin/netload, min-stable 0.12, 4 limbs enabled where the CAMPD overnight pre-positioning is real, forced 0.7-1.2% in-solve), (2) CT_PEAKER evening [15,21] netload drag replacing the temperature-only CT limbs (6 zones, rho 0.49-0.71, forced 5.0-7.5% in-solve \u2014 under the 15% peaker cap; D-1/D-2/D-4 all pass). The MISO CHP steam-credit HR correction was audited and LEFT OFF (MISO CHP does not over-deliver). Recipe byte-unchanged vs miso-46; every delta is one of these two drag mechanisms in reliability_floor_coeffs_MISO.csv.", "file": "frontend/data/backcast/runs/2026-07-08-miso-47-steamgas-ct.js", "id": "2026-07-08-miso-47-steamgas-ct", "iso": "MISO", "label": "miso 47 steamgas ct", "market_story": "CT_PEAKER: MISO commits simple-cycle peakers for local Resource Adequacy through the afternoon-evening net-load ramp (the duck-neck: cooling load climbs while solar collapses at sunset); the evening [15,21] net-load floor reproduces that committed evening SHAPE the energy-only LP decommits (D-1 diurnal r~0.99, forced 5-7.5% under the peaker budget). ST_GAS: legacy gas-steam boilers are held warm at physical min-stable (0.12) through the overnight [0,6] trough on extreme-temperature / high-net-load days to ramp for the NEXT peak rather than pay a multi-hour cold start (forced 0.7-1.2%). Both are commitment scaffolding, not volume levers - the residual CT/ST_GAS annual under-run is a separate merit-position model miss (disclosed), not what the floor buys.", "shorthand": "miso-47-steamgas-ct", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "(ABLATION TWIN of 2026-07-08-miso-48-stgas-srmc) Zero-forcing reference solve: the miso-48 recipe with every merchant floor/bridge/drag neutralized (reliability_floor OFF - the ST_GAS overnight + CT_PEAKER evening drag limbs removed), keeping the structural protected set (nuclear must-run, CHP steam, coal take-or-pay). Isolates what the drag limbs buy under the re-grounded ST_GAS_INTERMEDIATE SRMC floor: CT_PEAKER +0.66/+0.46/+0.33 TWh (2023/24/25) vs the twin, displacing mostly COAL_PRB/CC_REGULAR; the ST_GAS overnight limbs force <0.1 TWh net class energy. Same magnitudes as the miso-47 twin - the offer-floor change does not lean on the floors (rule 21 DOF evidence).", "file": "frontend/data/backcast/runs/2026-07-08-miso-48-stgas-ablation.js", "id": "2026-07-08-miso-48-stgas-ablation", "iso": "MISO", "label": "miso 48 stgas ablation", "shorthand": "miso-48-stgas-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-miso-48-stgas-ablation", "date": "2026-07-08", "definition": "MISO 48 ST_GAS_INTERMEDIATE SRMC-floor re-ground keeper candidate: the miso-47 keeper recipe re-solved byte-identical at HEAD with ONE offer-curve change - the generic ST_GAS_INTERMEDIATE committed band raised 0.85 -> 1.00x base_HR (backcast_config.py), closing the pjm-83 defect pattern from the L-7 SRMC-floor audit (docs/miso-caiso-srmc-floor-audit-2026-07.md SS2, G-21/#1302): an uncited generic sub-1.0 multiplier priced the five near-baseload MISO steam boilers (Harding Street, Ames, Nine Mile Point, Lewis Creek, Sabine) ~$3.3-5.2/MWh below the MISO cost-based-offer floor (Tariff Module C / Attachment L; IMM/Potomac SOM sanity). CC_REGULAR econ_low 0.95 untouched (the recognized CC flat-plateau CAMPD exception). Zero free parameters: a tariff-cited bound replaces a residual-lineage value; LOO degenerates to per-year direction checks, consistent all three years. Structure fix promoted on correctness (rules 1/11/14): 2023 ST_GAS crosses the C1 band edge (-7.56 -> -8.16 TWh, C1 14/16 -> 13/16) because the sub-SRMC band was buying ~0.6 TWh/yr of masked G-25 commitment-posture energy (now correctly attributed); C3a mean LMP improves in ALL years (2023 -0.1%, 2024 -4.7%, 2025 -10.7%). Everything else in the miso-47 recipe unchanged.", "file": "frontend/data/backcast/runs/2026-07-08-miso-48-stgas-srmc.js", "id": "2026-07-08-miso-48-stgas-srmc", "iso": "MISO", "label": "miso 48 stgas srmc", "market_story": "CT_PEAKER: MISO commits simple-cycle peakers for local Resource Adequacy through the afternoon-evening net-load ramp (the duck-neck: cooling load climbs while solar collapses at sunset); the evening [15,21] net-load floor reproduces that committed evening SHAPE the energy-only LP decommits (D-1 diurnal r~0.99, forced 5-7.5% under the peaker budget). ST_GAS: legacy gas-steam boilers are held warm at physical min-stable (0.12) through the overnight [0,6] trough on extreme-temperature / high-net-load days to ramp for the NEXT peak rather than pay a multi-hour cold start (forced 0.7-1.2%). Both are commitment scaffolding, not volume levers - the residual CT/ST_GAS annual under-run is a separate merit-position model miss (disclosed), not what the floor buys.", "shorthand": "miso-48-stgas-srmc", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-miso-49-tempderate-ablation", "date": "2026-07-08", "definition": "MISO 49 KEEPER (promoted 2026-07-09, supersedes miso-48-stgas-srmc): the miso-48 keeper's exact recipe (sourced from its own meta.json) re-solved at HEAD with ONLY temp_dependent_derate=True added -- the per-class dry-bulb-temperature capacity derate curve (CC/CT capacity-neutral reshape, COAL/ST_GAS additive hot-hour derate) replacing the flat net-summer treatment, per docs/handoffs/temp-derate-keeper-rerun-playbook-2026-07.md. A real, literature-cited physical mechanism (arXiv:2311.07001; CPUC R.21-10-002), not fit to any residual -- kept on structure (rule 1) independent of its fit effect, and validated via the rule-20 zero-forcing ablation twin (near-identical result with all commitment floors off). C3c scarcity tail (energy-only LMP dual, >$200): miso-48's own model was 0/0/0h (2023/24/25) vs DA actual 1/24/38h; miso-49 is 0/6/3h -- a partial, non-closing improvement in 2024 (25% of the gap) and 2025 (8%), no change in 2023 (actual is only 1h there). C3a mean LMP: 2023/2024 both PASS (DA-diagnostic side rows -2.5%/-1.0%), 2025 -10.7% -> -8.7% (still CAVEAT/commercial-band, narrower vs miso-48). C1 fuel-mix 13/16 -> 14/16, but the flipped row (2023 ST_GAS -8.16 -> -7.99 TWh) is a marginal edge-of-band move, not a structural fix. C2 system volume (2025 gas/coal) is unchanged (-14.7%/+16.3%, same pre-existing coal-for-gas substitution miss). C7 diurnal shape and C8 forced-energy share both still PASS -- the capacity reshape does not push any floor/bridge over its budget. Determination: NOT-YET (same as miso-48; same undocumented FAIL surface: fuelmix, sysvol, price_tail), governance PASS (calibration_attestation.json carries the DOF ledger + the new temp_dependent_derate entry, measured-physical, 6 cited scalars). Zero-forcing ablation twin registered as 2026-07-09-miso-49-tempderate-ablation. Next queued: coal sigmoid fix.", "file": "frontend/data/backcast/runs/2026-07-08-miso-49-tempderate.js", "id": "2026-07-08-miso-49-tempderate", "iso": "MISO", "label": "miso 49 tempderate", "shorthand": "miso-49-tempderate", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "D-7 statistical-mode A/B twin \u2014 SAME-SHA replay of the CURRENT MISO keeper 2026-07-08-miso-47-steamgas-ct (bundle MISO/miso_47_steamgas_ct_drag), replayed at HEAD fab2254 with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False); structural model + realized annual Henry Hub gas price unchanged. G-10 honesty-gate twin: first re-solve of any kind since the original 2026-07-03 miso-39 probe \u2014 the D-7 gap is now same-SHA-comparable to the current keeper (miso-41/miso-44/miso-47 were never re-gated). Fail count 4\u219211 of 11 scored (C6 governance excluded) \u2014 fails EVERY scored criterion with overlays off, the starkest gap of the four in-scope ISOs. Overlay-carried coal fleet confirmed: fuel-mix C1 COAL_PRB 122\u2192174 TWh, sysvol C2 coal +61%, CO2 C5a PASS\u2192FAIL (~\u22122%\u2192+15\u201322%), dispatch-corr C4 PASS\u2192FAIL, diurnal shape C7 PASS\u2192FAIL, C8 forced-share PASS\u2192FAIL, price level C3a \u22124%\u2192\u221224% \u2026 \u221212.8%\u2192\u221230.4% vs DA. None of MISO's in-sample fit generalizes as a forecast-machinery prior. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-08-miso47-statmode.js", "id": "2026-07-08-miso47-statmode", "iso": "MISO", "label": "miso47 statmode", "shorthand": "miso47-statmode", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-neiso54-steamgas-ct-ablation", "date": "2026-07-08", "definition": "NEISO extreme-day reliability drag on the neiso-53 keeper recipe (winter fuel-security stack + reliability_floor), the only delta living in reliability_floor_coeffs_NEISO.csv. (1) CT_PEAKER EVENING-RAMP DRAG: evening-windowed [15,21] tmax/netload limbs at commit_frac x min_stable (0.38) - the peakers' local-RA net-load-ramp commitment (5 enabled: Boston tmax+netload, Connecticut tmax+netload, North netload; rho>=0.3, n>=30, commit>baseline). Replaces the 2026-07-05 scrubbed all-24h limbs; the evening window clears D-4 off-window (PASS) and lands CT profile_r 0.97-0.98. CT_PEAKER is 0.5-0.7% of ISO load (<2%), so its 26-30% in-window forced share is reported-not-gated (rule 20 v2.1); C8 PASSES. (2) ST_GAS -> COMPONENT B: the lone 81 MW ST_GAS unit sits in a mixed CAMPD facility (no clean pure-play signal), so its overnight limbs ship as visible disabled placeholders and its commitment is owned entirely by the winter fuel-security must-run (Component B) - one program-grounded mechanism, replacing the contaminated all-24h netload limb (rule 14/19). VERDICT: CALIBRATED-WITH-CAVEATS, 0 FAILs, identical to neiso-53 (C1 12/12 free 8/8 PASS, C3a/C3b commercial-band, C3c/C5b ledgered winter-scarcity, C7 SKIPPED immaterial, C8 PASS) - the drag adds real structure the scrub had removed with no scored-metric change and no winter degradation (rule 1). Ablation twin + keeper promotion pending owner sign-off.", "file": "frontend/data/backcast/runs/2026-07-08-neiso-54-steamgas-ct.js", "id": "2026-07-08-neiso-54-steamgas-ct", "iso": "NEISO", "label": "neiso 54 steamgas ct", "market_story": "CT_PEAKER +0.087/+0.066/-0.000 TWh vs the zero-forcing twin: NEISO commits its simple-cycle peakers for LOCAL RESOURCE ADEQUACY through the afternoon-evening net-load ramp (cooling load climbs as solar sets) - the real ISO-NE forward-reserve/RA commitment the energy-only LP omits; the floor binds only the evening [15,21] window on hot/high-netload days (D-4 PASS), commits ~0.07-0.09 TWh in the ramp-stress years, and is price-near-neutral (avg LMP within $0.7). ST_GAS +0.024/+0.019/+0.020 TWh: the lone fuel-secure steam unit is postured on winter cold days by the winter fuel-security must-run (Component B, WRP/IEP/OFSA). Both classes are immaterial (<0.7% of ISO load), so the drag adds real, forward-derivable market STRUCTURE with no scored-metric change - a rule-1 faithfulness gain, not a residual fit.", "shorthand": "neiso-54-steamgas-ct", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-neiso-55-temp-derate", "date": "2026-07-08", "definition": "Prior NEISO keeper (superseded 2026-07-09 by 2026-07-09-neiso-56-reserve-coopt, which adds the dormant ISO-NE RCPF reserve co-optimization on this exact recipe). The neiso-54 recipe (winter fuel-security + CT evening-ramp / ST_GAS Component-B reliability drag) plus the physically-grounded temp_dependent_derate (per-class dry-bulb capacity curve replacing the flat net-summer derate; arXiv:2311.07001, CPUC R.21-10-002). Promoted on rule-1 structural fidelity, not fit: C3a mean-LMP improved to all-PASS, C3c scarcity tail unchanged (0h, winter gap dormant), C5b storage marginally deeper. CALIBRATED-WITH-CAVEATS (C3c/C5b ledgered).", "file": "frontend/data/backcast/runs/2026-07-08-neiso-55-temp-derate.js", "id": "2026-07-08-neiso-55-temp-derate", "iso": "NEISO", "label": "neiso 55 temp derate", "market_story": "temp_dependent_derate reshapes thermal available capacity by measured hourly zone temperature: gas CC/CT lose output on heatwave hours (air-density/mass-flow limit) and recover it on cool hours (capacity-neutral over the summer mean); coal/steam-gas take an additive hot-hour derate (condenser limit). It replaces a flat season-average net-summer number with the real physical temperature dependence. On NEISO the keeper-vs-twin delta is small (the class floors it shares with neiso-54 are unchanged); the derate itself is a real availability physics, not a residual-buying floor - its effect is a modest summer/shoulder capacity reshape, dormant on the winter cold-hour tail where NEISO's scarcity actually forms.", "shorthand": "neiso-55-temp-derate", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "(ABLATION TWIN of 2026-07-08-neiso-54-steamgas-ct) Zero-forcing reference: the neiso-54 recipe with every merchant floor/bridge OFF (--zero-forcing-ablation) - CT_PEAKER evening reliability drag and the winter fuel-security must-run (Component B) neutralized, keeping only nuclear must-run / CHP steam-following / coal take-or-pay and the physical availability derate + fuel pricing. Isolates what the drag + Component B buy: CT_PEAKER +0.087/+0.066/-0.000 TWh, ST_GAS +0.024/+0.019/+0.020 TWh (2023/24/25), avg LMP -$0.25/-0.32/-0.64 - immaterial, confirming the keeper is not floor-dependent.", "file": "frontend/data/backcast/runs/2026-07-08-neiso54-steamgas-ct-ablation.js", "id": "2026-07-08-neiso54-steamgas-ct-ablation", "iso": "NEISO", "label": "neiso54 steamgas ct ablation", "shorthand": "neiso54-steamgas-ct-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "PJM 89 steam-gas overnight-drag CANDIDATE (not yet promoted keeper; pjm-83 remains keeper pending CC_CHP fix + ablation/LOO). pjm-83 recipe re-solved at HEAD absorbing four structural corrections vs pjm-83: (1) ST_GAS extreme-day OVERNIGHT [0,6] drag in the reliability_floor engine (tmax/tmin/netload day-triggers, min-must-run floor, 7 limbs enabled where the driver is real, forced-energy 3.4-6.1%); (2) CHP steam-credit power-only HR correction extended to PJM; (3) PRB 5-13d dead-stop + orphaned ST_CHP steam-boiler outage capture; (4) coal-bit econ-high held at 1.2664. VALIDATED: CT_CHP corrected 2.0->1.4-1.5 TWh (near 923); coal 146.0 vs 145.9 (EIA-930); ST_GAS drag healthy (D-1/D-2 PASS). OPEN RESIDUAL: CC_CHP still ~+50% over 923 net-to-grid - its offer multipliers (0.66x) negate the HR floor; the pending lever is merchant BTM host-share re-sizing.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-89-steamgas-drag.js", "id": "2026-07-08-pjm-89-steamgas-drag", "iso": "PJM", "label": "pjm 89 steamgas drag", "shorthand": "pjm-89-steamgas-drag", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "ABLATION TWIN of 2026-07-08-pjm-90-cchp-srmc (CLAUDE.md rule 21): the pjm-90 recipe verbatim with every merchant floor/bridge/drag neutralized (ScenarioConfig.as_zero_forcing_ablation), structural protected set kept (nuclear must-run, CHP steam, coal take-or-pay). Reference for the keeper-vs-twin per-class delta.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-90-cchp-ablation.js", "id": "2026-07-08-pjm-90-cchp-ablation", "iso": "PJM", "label": "pjm 90 cchp ablation", "shorthand": "pjm-90-cchp-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-pjm-90-cchp-ablation", "date": "2026-07-08", "definition": "PJM 90 CC_CHP SRMC re-grounding on the pjm-89 steam-gas-drag recipe. Completes the pjm-79 SRMC re-grounding for the one class it skipped: CC_CHP economic tranches 0.6624/0.684/0.8208 -> 1.0/1.0/1.05 (Manual-15 composite-cost floor). Measured diagnosis: CC_CHP over-DISPATCHED (grid CF ~48% vs measured net-to-grid ~29%) by bidding sub-SRMC, NOT a BTM capacity issue (merchant 35% BTM is the correct host share). The steam credit is the host's (BTM-removed) so the grid MWh bids at true power-only cost; must-run steam floor untouched. Rule 1 offer physics, registered channel. RESULT vs 923 net-to-grid: CC_CHP 2024 10.7->8.7 TWh (+47%->+19%), 2025 9.6->7.3 (+52%->+16%), 2023 10.0->9.1 (+50%). Aggregate held: coal 122 vs 121 (EIA-930), prices flat. Carries all four pjm-89 corrections (ST_GAS overnight drag, CHP HR, outage capture, coal-bit). OPEN: 2023 CC_CHP still +50%; the last mile is a measured grid-export availability cap (net-export envelope, like retiree_cems_cap) - flagged for owner sign-off (rule-11 framing). KEEPER PROMOTED 2026-07-08, ablation twin registered (2026-07-08-pjm-90-cchp-ablation). Determination NOT-YET: fails C1 fuel-mix (CC_REGULAR 2023 -11.3 TWh / 2024 +13.5 TWh, ST_GAS 2024 -8.0 TWh - volume out of band) and C3c price-tail/scarcity (2025: model 0h vs DA actual 51h >$200) - both pre-existing PJM model misses, not introduced by this change; C2 system volume, C6 governance, C7 diurnal shape and C8 forced-energy all PASS.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-90-cchp-srmc.js", "id": "2026-07-08-pjm-90-cchp-srmc", "iso": "PJM", "label": "pjm 90 cchp srmc", "market_story": "ST_GAS +0.05/0.22 TWh (2024/25): the overnight [0,6] drag is RUC-style reliability commitment holding legacy gas-steam boilers warm at min-load on extreme-temperature / high-net-load days (PJM commits these out-of-merit for local/system reliability) \u2014 a thin scaffolding the LP dispatches above, not a volume driver. CT_PEAKER -0.4/-1.1 TWh: the ct_netload_drag holds fast-start peakers in the evening net-load ramp, but with all floors removed the ablation lets CT clear the freed cheap energy economically, so the net cross-class delta is merit-order redistribution, not a CT-specific forced buy. CC_CHP/CT_CHP/COAL deltas <0.15 TWh \u2014 the offer/HR/outage corrections move level via price, not forcing.", "shorthand": "pjm-90-cchp-srmc", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "D-7 statistical-mode A/B twin \u2014 SAME-SHA replay of the CURRENT PJM keeper 2026-07-08-pjm-90-cchp-srmc (bundle pjm90_cchp_srmc), replayed at HEAD fab2254 with every per-hour/per-year answer-injection overlay off (outage_source=statistical, ct_deployment_overlay=False, reliability_deployment_overlay=False, wefor_residual/groups=None, coal_plant_monthly_pricing=False); structural model + realized annual Henry Hub gas price unchanged. G-10 honesty-gate twin: first re-solve of any kind since the original 2026-07-03 pjm-76 probe \u2014 the D-7 gap is now same-SHA-comparable to the current keeper (pjm-77/pjm-83/pjm-90 were never re-gated). Fail count 2\u21928 of 11 scored (C6 governance excluded), the largest swing of the four in-scope ISOs. Overlay-carried coal/gas split confirmed: fuel-mix C1 COAL_BIT balloons 112\u2192213 TWh, sysvol C2 PASS\u2192FAIL (coal +61.5%), CO2 C5a PASS\u2192FAIL (~\u22121%\u2192+22\u201326%), dispatch-corr C4 PASS\u2192FAIL (coal r 0.93\u21920.80), price level C3a CAVEAT\u2192FAIL (+3.1%\u2192\u221215.2% \u2026 \u221210.2%\u2192\u221223.8% vs DA), C8 forced-share PASS\u2192FAIL. The historic-outage overlay is doing the heaviest lifting on PJM's coal fleet. Probe only \u2014 not a keeper, per CLAUDE.md #1/#13.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-91-statmode.js", "id": "2026-07-08-pjm-91-statmode", "iso": "PJM", "label": "pjm 91 statmode", "shorthand": "pjm-91-statmode", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "(PROBE) PJM 92 GT ambient-temperature capacity derate on the pjm-90 recipe: adds config.gt_ambient_derate (CC 0.4 %/C, CT 0.6 %/C above a 35 C net-summer reference x measured hourly zone tmax) \u2014 the physically-correct incremental hot-hour GT derate the EIA-860 net-summer rating omits. Rule-11 physical input (physics slope x measured temperature), forward-reproducible; NOT tuned to the residual. VERDICT vs pjm-90 keeper: essentially unchanged \u2014 C1 still FAIL (2024 CC_REGULAR +13.5 TWh, ST_GAS -8.0), C3c still FAIL (2025 2h vs 51h, up from 0h). Diagnostic conclusion: the summer scarcity tail is NOT a capacity leak. Measured net-summer already captures the summer ambient derate (incremental ~0.3 GW at peak), there are no phantom retirements/mothballs, and the energy+reserve co-opt cannot bind (deliverable reserve-supply cap ~48 GW vs ~3.3 GW measured Primary requirement \u2014 reserve is effectively ramp-unlimited). The tail is a price-formation/mechanism issue (Issue C: ramp-unbounded reserve supply + monthly gas smoothing daily heat-wave basis spikes), not overstated capacity \u2014 so the derate is kept as correct structure but does NOT recover scarcity. pjm-90 stays keeper. Otherwise the pjm-90 recipe verbatim.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-92-ambient-derate.js", "id": "2026-07-08-pjm-92-ambient-derate", "iso": "PJM", "label": "pjm 92 ambient derate", "shorthand": "pjm-92-ambient-derate", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-08-pjm-93-temp-derate-ablation", "date": "2026-07-08", "definition": "PJM 93 temperature-dependent derate on the pjm-90 CC_CHP SRMC recipe. Carries the pjm-90 recipe verbatim (ST_GAS overnight drag, CHP power-only HR correction, PRB/ST_CHP outage capture, CC_CHP SRMC re-grounding) and adds temp_dependent_derate=True: a physically-derived per-class dry-bulb temperature capacity curve (arXiv:2311.07001, CPUC R.21-10-002) that REPLACES the flat EIA-860 net-summer derate for CC/CT with a capacity-neutral reshape (heatwave hours below net-summer, cooler hours toward full rating) and adds a pure additive hot-hour derate for COAL/ST_GAS. RESULT: 2025 C3c scarcity tail (DA-expressible hours >$200) improved 0h->19h vs 51h actual (0.00x->0.37x, 37% of the undershoot closed, the keeper's own flagged gap); 2023 0h->2h (actual 8h) and 2024 4h->12h (actual 2h), both still small-count PASS. C1 fuel-mix (CC_REGULAR, ST_GAS) essentially unchanged -- this mechanism reshapes capacity by temperature, it does not resolve the fuel-mix volume miss (2024 ST_GAS crosses into tolerance marginally, -8.0->-7.9 TWh). No regression on any other criterion vs pjm-90: C2 system volume, C4 dispatch correlation, C5a CO2, C7 diurnal shape and C8 forced-energy all PASS; forced-energy shares and the pre-existing reliability_floor x CT_PEAKER D-4 off-window flag are unchanged. KEEPER PROMOTED 2026-07-09 (reviewed as probe 2026-07-08-pjm-93-temp-derate first, no promotion-blocking regression found), ablation twin registered (2026-07-08-pjm-93-temp-derate-ablation). Determination NOT-YET: fails C1 fuel-mix (CC_REGULAR 2023 -12.8 TWh / 2024 +11.7 TWh - volume out of band) and C3c price-tail/scarcity (2025: model 19h vs DA actual 51h >$200, 0.37x) - both pre-existing PJM model misses carried over from pjm-90, not introduced by this change; C2 system volume, C6 governance, C7 diurnal shape and C8 forced-energy all PASS.", "file": "frontend/data/backcast/runs/2026-07-08-pjm-93-temp-derate.js", "id": "2026-07-08-pjm-93-temp-derate", "iso": "PJM", "label": "pjm 93 temp derate", "market_story": "CT_PEAKER -0.55/-1.12 TWh (2024/25): ct_netload_drag holds fast-start peakers in the evening net-load ramp, but with all floors removed the ablation lets CT clear the freed cheap energy economically -- the net cross-class delta is merit-order redistribution, not a CT-specific forced buy (same story as pjm-90). CC_REGULAR +0.34/+0.75 TWh in 2023/24 but flips to -0.35 TWh in 2025; ST_GAS +0.14/+0.08/+0.29 TWh across 2023-25: the reliability_floor overnight drag directly forces only 0.06-0.23 TWh (CC_REGULAR) / 0.21-0.28 TWh (ST_GAS) of that each year (measured CAMPD-derived commitment floor, RUC-style reliability commitment on extreme-temperature/high-net-load nights); the remainder -- including the 2025 CC_REGULAR sign flip -- is indirect economic redispatch as the floors removed elsewhere (chiefly CT_PEAKER/import) reshape the LP's clearing order, not a forced buy. COAL_BIT +2.7-4.4 TWh and import -2.6-3.6 TWh: neither class is directly floored (coal_mustrun_per_plant is unchanged between main and ablation) -- this is the system-wide merit-order echo of the floors removed on CT_PEAKER/CC_REGULAR/ST_GAS reshaping the LP's clearing order, not a forced buy. CC_CHP/CT_CHP/ST_CHP deltas <=0.15 TWh -- the offer/HR/outage corrections move level via price, not forcing.", "shorthand": "pjm-93-temp-derate", "years": [2023, 2024, 2025]}, {"date": "2026-07-08", "definition": "temp-derate full-keeper ablation -- pjm90_cchp_srmc config + temp_dependent_derate, 2023-2025 (ABLATION TWIN of 2026-07-08-pjm-93-temp-derate)", "file": "frontend/data/backcast/runs/2026-07-08-pjm-93-temp-derate-ablation.js", "id": "2026-07-08-pjm-93-temp-derate-ablation", "iso": "PJM", "label": "pjm 93 temp derate (ABLATION TWIN)", "shorthand": "pjm-93-temp-derate-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(PROBE \u2014 ABLATION TWIN of 2026-07-09-caiso-69-sp15split-dragoff, rule 21) SP15-split ablation -- caiso-68 recipe (caiso65 keeper config + temp_dependent_derate) on the LA_BASIN/SDGE/SP15_rest split topology, ct_netload_drag=False per-run override, every merchant floor/bridge neutralized, 2023-2025. Notable: CT_PEAKER clears MORE on pure merit here (2.02/1.41/0.98 TWh) than in the main run with the RA bridge on (0.90/0.91/0.79) \u2014 the bridge's forced CC min-gen crowds peakers out of the SoCal pockets; see the main sidecar's 2026-07-09 scoring correction (the A/B's 'actual SP15 $118-127' targets were a demand-field misread; measured DA actuals are SP15 $49.39/$32.68/$32.22, below NP15).", "file": "frontend/data/backcast/runs/2026-07-09-caiso-69-sp15split-ablation.js", "id": "2026-07-09-caiso-69-sp15split-ablation", "iso": "CAISO", "label": "caiso 69 sp15split ablation", "shorthand": "caiso-69-sp15split-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-caiso-69-sp15split-ablation", "date": "2026-07-09", "definition": "(PROBE \u2014 pre-registered A/B, negative result) SP15-split main -- caiso-68 recipe (caiso65 keeper config + temp_dependent_derate) on the LA_BASIN/SDGE/SP15_rest split topology, ct_netload_drag=False per-run override, 2023-2025 RESULT: pocket links bind (SDGE ~1,000-1,240 h/yr at its 1,436 MW cap, LA 0-256 h) but form only ~$1-4 mean premium; CT_PEAKER collapses to 0.79-0.94 TWh without the drag (vs 1.56-2.10 with it; actual 3.09-5.24): the split alone cannot carry CT dispatch. 2023 hrs>$200 530 vs actual 21 (unchanged \u2014 stack-top gas, not copperplate). C8 forced-share FAIL->PASS (D-2 CT drag share 56/53/55% -> 0.8/1.4/0.0%, RA-bridge remnant only), C5a FAIL->CAVEAT, C7 PASS->FAIL (merit CT profile_r 0.76/0.76/0.68 vs 0.8 gate \u2014 the drag was carrying CT's diurnal shape). SCORING CORRECTION (2026-07-09, supersedes this sidecar's original text and the A/B LMP targets in both SP15-split handoff docs): the 'actual SP15 $118-127' those targets quoted was a misread of the run payload's lmp[zone].d field, which is the dashboard demand WEIGHT (sum of monthly mean zonal load in GW \u2014 backcast-runs.html ~line 331 uses it as the LMP weighting), not a price; the same misread would make ZP26's 'actual' $14. Measured DA hub actuals (data/raw/lmp-data/CAISO, groupby node mean) are SP15 $49.39/$32.68/$32.22 and NP15 $51.26/$40.67/$38.23 (2023/24/25) \u2014 so the model OVER-prices the SoCal pockets by ~$15-21 (model $47-71) and actual SP15 clears BELOW NP15 (+$1.9/+$8.0/+$6.0 NP15-SP15); there is no missing $48-78 premium to close. The earlier redirect ('offer level above SRMC + tighter-than-LCT local limits') is therefore wrong-directional \u2014 raising SoCal offers or tightening pocket limits would worsen an existing overshoot. Corrected redirect: the CT gap is a commitment/AS-dispatch question, not a price-level one \u2014 note the zero-forcing ablation clears MORE CT than this run (2.02/1.41/0.98 vs 0.90/0.91/0.79 TWh), i.e. the RA bridge's forced CC min-gen crowds peakers out of the very pockets that should call them; reserve/AS co-optimization dispatching CTs (RTPD/RUC-like) is the missing forward-real driver. Not promotable (7 fails incl. C7); the split topology itself is structurally sound (links bind with measured LCT caps, zero fitted parameters) and worth keeping under a future commitment-side fix.", "file": "frontend/data/backcast/runs/2026-07-09-caiso-69-sp15split-dragoff.js", "id": "2026-07-09-caiso-69-sp15split-dragoff", "iso": "CAISO", "label": "caiso 69 sp15split dragoff", "shorthand": "caiso-69-sp15split-dragoff", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "Offer-curve re-derivation under temp_dependent_derate (rule 1: keep the physical derate, re-derive the offer LEVEL): ercot46_clock_steamgas config + temp derate, with the keeper's fitted scarcity walls stripped to physically-grounded values -- CC_REGULAR peak 4.58->2.25 (F-class duct-burner ratio), CC_REGULAR/CC_CHP econ_high ->1.27 (CAMPD CC marginal-HR reach), CT_PEAKER peak 13.15->4.0 (de-fits the encoded $5,000 ORDC wall the multiproduct co-opt now prices endogenously), ST_GAS peak 3.2->2.2; committed/econ_low bands unchanged. A/B vs ercot48-tempderate-full-probe (identical config, keeper curves): C3a mean-LMP error +269/+161/+42% -> +264/+156/+36%, C3b NRMSE 4.50/2.91/0.62 -> 4.42/2.85/0.56, C3c tail 328/100/42 h vs DA actual 311/68/23 (PASS all years) -- the offer top-of-stack is INERT on the temp-derate C3a/C3b blow-out. Diagnosis (2023): the overshoot is ~210 reserve-shortfall hours priced $1,000-5,000 by the co-opt ORDC steps plus 65 load-shed hours at VOLL (~$8.9k, mean 1.2 GW slack), not offer-set; measured telemetry contradicts the modeled scarcity -- median RTOLCAP in those model-deep hours was 6.9 GW (RTORPA $13.8) / 8.3 GW (RTORPA $0.3): the availability stack under temp derate sits ~5-7 GW below the real system's measured online capability in the scarcity window. Offer re-tuning cannot (and per rule 1 must not) close this; root cause is the hot-hour availability level vs measured RTOLHSL/RTOLCAP. PROBE, not a promotion; keeper stays ercot46. || REJECTED WITH CAUSE (owner decision 2026-07-09): the temp-derate line is closed for ERCOT. Cause: the fleet's own measured behaviour refutes the literature slopes \u2014 scarcity-hour (RT>$200) capability slope fitted above 34C is ~0 or negative for every gas class (CC -0.27, CT -0.04, ST_GAS -0.29, CC_CHP -1.41 %/degC vs model +0.76/+1.26/+0.54; online CT p90 = 1.00-1.02x rating in every bin 30-46C), production at TMAX>=40C reached 95-100%+ of net-summer rating for most capacity, and telemetered RTOLCAP showed 6.9-8.3 GW spare in the model's deep hours (scripts/probes/_ercot_temp_capability_envelope.py; calibration-log 2026-07-09). The measured ERCOT parameterization is slope~0 above rating = the keeper's flat net-summer treatment. Keeper stays 2026-07-08-ercot46-clock-steamgas; the thin-tail miss routes to the measured DAM offer-surface path (G-22 SS5.1 / ercot37 SS8).", "file": "frontend/data/backcast/runs/2026-07-09-ercot49-offer-retune-tempderate.js", "id": "2026-07-09-ercot49-offer-retune-tempderate", "iso": "ERCOT", "label": "ercot49 offer retune tempderate", "shorthand": "ercot49-offer-retune-tempderate", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "Zero-forcing ablation twin of 2026-07-09-ercot49-offer-retune-tempderate (rule 20 / audit D-3): identical config (temp derate + c1 physical-top offer curves, 2023-2025) with every commitment/min-gen floor off. C3a +512/+442/+231%, C3b NRMSE 7.14/6.47/3.58, C3c 612/250/183 h -- without the forcing scaffolding the scarcity cascade deepens (~2x the main arm's tail), confirming the floors depress rather than create the deep-tail overshoot; the overshoot is availability-driven (see main-arm definition). || REJECTED WITH CAUSE (owner decision 2026-07-09): the temp-derate line is closed for ERCOT. Cause: the fleet's own measured behaviour refutes the literature slopes \u2014 scarcity-hour (RT>$200) capability slope fitted above 34C is ~0 or negative for every gas class (CC -0.27, CT -0.04, ST_GAS -0.29, CC_CHP -1.41 %/degC vs model +0.76/+1.26/+0.54; online CT p90 = 1.00-1.02x rating in every bin 30-46C), production at TMAX>=40C reached 95-100%+ of net-summer rating for most capacity, and telemetered RTOLCAP showed 6.9-8.3 GW spare in the model's deep hours (scripts/probes/_ercot_temp_capability_envelope.py; calibration-log 2026-07-09). The measured ERCOT parameterization is slope~0 above rating = the keeper's flat net-summer treatment. Keeper stays 2026-07-08-ercot46-clock-steamgas; the thin-tail miss routes to the measured DAM offer-surface path (G-22 SS5.1 / ercot37 SS8).", "file": "frontend/data/backcast/runs/2026-07-09-ercot49-retune-tempderate-ablation.js", "id": "2026-07-09-ercot49-retune-tempderate-ablation", "iso": "ERCOT", "label": "ercot49 retune tempderate ablation", "shorthand": "ercot49-retune-tempderate-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "G-22 \u00a78 heterogeneity-preserving condition-responsive offer surface (ercot_offer_surface_conditional=True, years [2023, 2024, 2025]) -- ercot46_clock_steamgas config reconstructed from meta.json; offer curves and temp_dependent_derate unchanged", "file": "frontend/data/backcast/runs/2026-07-09-ercot50-offer-surface-conditional.js", "id": "2026-07-09-ercot50-offer-surface-conditional", "iso": "ERCOT", "label": "ercot50 offer surface conditional", "shorthand": "ercot50-offer-surface-conditional", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "G-22 \u00a78 heterogeneity-preserving condition-responsive offer surface (ercot_offer_surface_conditional=False, years [2023, 2024, 2025]) -- ercot46_clock_steamgas config reconstructed from meta.json; offer curves and temp_dependent_derate unchanged", "file": "frontend/data/backcast/runs/2026-07-09-ercot50-surface-control-ablation.js", "id": "2026-07-09-ercot50-surface-control-ablation", "iso": "ERCOT", "label": "ercot50 surface control ablation", "shorthand": "ercot50-surface-control-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "G-22 \u00a78 heterogeneity-preserving condition-responsive offer surface (ercot_offer_surface_conditional=False, years [2023, 2024, 2025]) -- ercot46_clock_steamgas config reconstructed from meta.json; offer curves and temp_dependent_derate unchanged", "file": "frontend/data/backcast/runs/2026-07-09-ercot51-coal-netsummer-ablation.js", "id": "2026-07-09-ercot51-coal-netsummer-ablation", "iso": "ERCOT", "label": "ercot51 coal netsummer ablation", "shorthand": "ercot51-coal-netsummer-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "G-22 \u00a78 heterogeneity-preserving condition-responsive offer surface (ercot_offer_surface_conditional=False, years [2023, 2024, 2025]) -- ercot46_clock_steamgas config reconstructed from meta.json; offer curves and temp_dependent_derate unchanged", "file": "frontend/data/backcast/runs/2026-07-09-ercot51-coal-netsummer-derate.js", "id": "2026-07-09-ercot51-coal-netsummer-derate", "iso": "ERCOT", "label": "ercot51 coal netsummer derate", "shorthand": "ercot51-coal-netsummer-derate", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-ercot52-ordc-capdual-ablation", "date": "2026-07-09", "definition": "ercot52 ORDC cap-dual adder fix (KEEPER-TRACK CANDIDATE, NOT-YET/unattested; single delta on the ercot51 coal-net-summer-derate config = ercot_ordc_cap_dual_adder): the post-solve additive RTORPA sourced the total-family balance dual, which is already folded into the energy LMP whenever the PHYSICAL shared headroom (not the RTOLCAP cap row) is the binding reserve constraint -- every 2023 scarcity hour once the coal derate is on (solved cap-row dual = 0 in all 8760 h), so each shortage hour was priced twice. The fix sources the adder from the supply-cap rows' own duals, the exactly-uninternalized component by LP duality (lambda_balance = lambda_cap + mu_headroom; only mu passes into the energy dual). No new parameter, no price fit; dispatch/energy duals byte-identical to ercot51; offer-curve bands UNCHANGED from the ercot46 keeper. Rubric v2.4 (like-for-like load-weighted basis, the scoring-frame fix this candidate's diagnosis motivated -- docs/rubric-v24-price-basis-memo-2026-07.md): C3a -1.0%/-0.3%/-3.6% PASS all years, C3b 0.109 PASS / 0.296 FAIL / 0.079 PASS, C3c 162/37/5 h -- first ERCOT run to clear the C3c gate in 2023 (0.52x DA; 0.90x RT parity) and 2024 (0.54x). LOYO-consistent vs ercot51 in every year on both bases. Remaining blockers (honest misses, not frame): C3b-2024 = Aug +62.6% model scarcity real-2024 lacked + shoulder unders (May -33%), C3c-2025 tail under (5h vs 23 DA), C5c-2024 storage shape; C6 unattested. G-22 s8 offer surface re-tested ON on top and REJECTED again (+3.9 pp C3a for +4 C3c h). Keeper stays ercot46 pending the 2024-shape root cause (handoff: ercot53 thread) + owner attestation.", "file": "frontend/data/backcast/runs/2026-07-09-ercot52-ordc-capdual.js", "id": "2026-07-09-ercot52-ordc-capdual", "iso": "ERCOT", "label": "ercot52 ordc capdual", "market_story": "ST_GAS/CC floors carry CHP steam-hosts and RA/AS-committed steam units that bid to stay online through low-price hours (start cost + min-down); coal take-or-pay runs on sunk fuel; without them the fleet cold-cycles daily and the LP re-prices 300+ phantom scarcity hours (twin C3c 379/127/77 h vs 162/37/5) -- the floors buy commitment realism, not residual.", "shorthand": "ercot52-ordc-capdual", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(ABLATION TWIN of 2026-07-09-ercot52-ordc-capdual, rule 20/D-3) zero-forcing reference solve of the ercot52 ordc-capdual config: every merchant floor/bridge OFF (nuclear must-run, CHP steam-following, coal take-or-pay kept). C3a +137.5%/+148.9%/+52.0%, C3b 1.492/1.963/0.714, C3c 379/127/77 h -- the keeper-vs-twin per-class delta shows what each floor buys (commitment realism; without the floors the fleet cold-cycles daily and the LP re-prices phantom scarcity).", "file": "frontend/data/backcast/runs/2026-07-09-ercot52-ordc-capdual-ablation.js", "id": "2026-07-09-ercot52-ordc-capdual-ablation", "iso": "ERCOT", "label": "ercot52 ordc capdual ablation", "shorthand": "ercot52-ordc-capdual-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(ABLATION TWIN of 2026-07-08-miso-49-tempderate, PROBE not a keeper) Rule-20 zero-forcing reference for the temp-derate probe: every merchant commitment floor/bridge (CT evening window, ST_GAS overnight floor) OFF, everything else -- including temp_dependent_derate=True -- unchanged. Result is nearly indistinguishable from the main probe: C3c scarcity tail identical (0/6/3h vs DA actual 1/24/38h), C1 fuel-mix identical pass/fail pattern (14/16, only COAL_PRB 2023 magnitude nudges +8.84->+9.04 TWh), C2/C3a/C3b/C4/C5/C7/C8 all match to within noise. Read: the CT-evening and ST_GAS-overnight floors contribute negligibly to this run's dispatch/price outcome, so the modest C3c/C3a movement from temp_dependent_derate is not an artifact of those floors -- it survives with the forcing scaffolding removed.", "file": "frontend/data/backcast/runs/2026-07-09-miso-49-tempderate-ablation.js", "id": "2026-07-09-miso-49-tempderate-ablation", "iso": "MISO", "label": "miso 49 tempderate ablation", "shorthand": "miso-49-tempderate-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-miso-50-coalsigmoid-ablation", "date": "2026-07-09", "definition": "MISO 50 PROBE (not promoted; keeper stays miso-49): the miso-49 keeper recipe (temp_dependent_derate and all) re-solved 2023-2025 with ONE change -- COAL_SIGMOID_DEFAULTS[MISO] (the coal-vs-gas passthrough sigmoid: prb / prb_follower / bituminous) re-derived from measured coal-commodity price by scripts/derive_coal_sigmoid.py, retiring the ERCOT byte-copy gas_mid 2.85 / gas_slope 2.5 (issue #1347 / gap G-26). Rule-23 trigger: the #1803 intake added the EIA Annual Coal Report region f.o.b.-mine price + BLS PPI coal-mining series a real re-derivation needs; each parameter is grounded in that measured data (gas_mid = coal-vs-gas-CC merit crossover from region delivered cost -> PRB 3.19, bituminous 4.12; ceil = 1.0 cost-tracking; floor = gas-trough/crossover -> 0.687/0.598/0.532; gas_slope = 1/cross-region dispersion -> bituminous 1.09, single-region PRB 2.5). Fit to measured f.o.b./PPI movement, NEVER to the MISO residual (honesty gate; DOF ledger reclassifies COAL_SIGMOID_DEFAULTS[MISO] residual -> measured-physical, n_residual 4->3). DISCOVERED RESULT (rules 1/10/11, not tuned away): grounding the offer in measured f.o.b. makes cheap MISO coal MORE inframarginal, so the pre-existing coal-for-gas over-substitution WORSENS -- C1 2023 COAL_PRB +8.8->+30.6 TWh (COAL_BIT ->+13.9), C2 2025 coal +16.3%->+24.5% / gas -14.7%->-16.5%, C1 free 10/12->5/12, C3a 2023 -2.5%->+18.0%, C5a CO2 2023 ->+13.1%; C4 coal dispatch-corr FAILs; determination NOT-YET (unchanged label, more fails). C8 shows COAL only 0.1-0.2% forced, so the extra coal is ECONOMIC merit, not floor-forcing. This is the honest signal that the residual is a gas-side / daily-basin-spot-granularity root cause (annual ACR f.o.b. cannot resolve daily gas troughs; daily basin spot indices S&P/Argus-paywalled -- rule-23 granularity caveat), NOT a coal-offer-level artifact; the ERCOT byte-copy's shallower discount was silently compensating for it. Kept per rule 11 (accurate measured input); root-cause fix (gas daily shape / seam / commitment) is the open item, not an offer re-tune. Recommendation to owner: HOLD -- do not promote as a fit improvement; keep the measured params in-tree; keeper stays miso-49. Rule-20 zero-forcing ablation twin registered alongside. See docs/handoffs/coal-sigmoid-rederive-2026-07.md.", "file": "frontend/data/backcast/runs/2026-07-09-miso-50-coalsigmoid.js", "id": "2026-07-09-miso-50-coalsigmoid", "iso": "MISO", "label": "miso 50 coalsigmoid", "shorthand": "miso-50-coalsigmoid", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "Rule-20 zero-forcing ablation twin of 2026-07-09-miso-50-coalsigmoid (the MISO coal-sigmoid re-derive probe): same recipe with ALL commitment/forcing floors OFF. Result is near-identical to the main run -- COAL_PRB +30.60->+30.65, COAL_BIT +13.88->+13.91, 2024 COAL_PRB +27.06->+27.22 TWh -- confirming the coal-for-gas over-substitution the re-derive produces is 100% ECONOMIC merit (the measured cheap coal offer), NOT floor-forcing (C8 independently reads COAL 0.1-0.2% forced). This is the rule-20 evidence that the discovered coal over-run is a real gas-side / daily-basin-spot-granularity root cause, not a forcing artifact. Diagnostic reference, not a keeper. See docs/handoffs/coal-sigmoid-rederive-2026-07.md.", "file": "frontend/data/backcast/runs/2026-07-09-miso-50-coalsigmoid-ablation.js", "id": "2026-07-09-miso-50-coalsigmoid-ablation", "iso": "MISO", "label": "miso 50 coalsigmoid ablation", "shorthand": "miso-50-coalsigmoid-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-miso-51-gasdaily-hydro-ablation", "date": "2026-07-09", "definition": "MISO 51 PROBE (not promoted; keeper stays miso-49): the miso-49 keeper recipe re-solved at HEAD (which now carries the miso-50 re-derived measured coal sigmoid) with three measured-input changes, zero new fitted parameters, targeting the miso-50-identified gas-side daily-granularity root cause: (1) gas_daily_shape[MISO] -- measured daily Henry Hub within-month swing, mean-preserving over the per-plant EIA-923 monthly gas level (plus the fuel.py fix that stops the flat F923 monthly overwrite from erasing the daily shape -- latent for CAISO/NYISO/NEISO too); (2) hydro_backfill_year=2024 + hydro_eia930_monthly (2025 EIA-923 early release carries 14/160 MISO hydro plants, 0.97 of ~9.9 TWh); (3) the inherited measured sigmoid surface. WINS: hydro 2025 -8.9 -> -0.1 TWh; 2023 ST_GAS recovers (-4.8 -> +1.5 TWh raw vs miso-50); C3a 2024 +6.1% / 2025 -2.4% both PASS (miso-49 2025 was -8.7%); C3c scarcity tail OPENS for the first time in any MISO run -- 33/13/11 h vs DA actual 1/24/38 (miso-49: 0/6/3), 2024 PASSES at 0.54x, and the 2023 'overshoot' is 33 vs 30 h against the RT companion (our energy-only dual is RT-like). DISCOVERED RESULT (rules 1/10/11): the coal over-run does NOT move -- COAL_PRB +30.1/+25.1/+26.9, COAL_BIT +13.7/+15.6/+18.6 TWh -- because the coal passthrough sigmoid keys off the SAME daily-shaped gas series, so coal offers deepen their discount in lockstep on every trough day and the merit order never flips; the whipsaw also causes the NEW C4 2024 coal dispatch-corr FAIL (r=0.856) and C3b 2023/24 monthly-shape FAILs (0.277/0.289). Determination NOT-YET (fuelmix, sysvol, price_mean 2023 +17.7% inherited from the sigmoid re-derive, price_shape, price_tail, dispatch_corr). NEXT LEVER identified: key the coal sigmoid on the MONTHLY gas level (a fuel contract's discount posture reprices monthly, not on daily spot) while gas units keep the daily price -- expected to create the real flip days, clear the C4/C3b whipsaw regressions, and keep the C3c tail gains (probe miso-52, solving). Rule-20 zero-forcing ablation twin registered alongside. [CORRECTION from miso-52: the whipsaw attribution of the C4/C3b FAILs and the flip-day expectation were both refuted -- the monthly-keyed sigmoid reproduces miso-51's scorecard within noise, and C4 was already failing at miso-50. Those regressions arrived with the sigmoid re-derive itself; see miso-52.]", "file": "frontend/data/backcast/runs/2026-07-09-miso-51-gasdaily-hydro.js", "id": "2026-07-09-miso-51-gasdaily-hydro", "iso": "MISO", "label": "miso 51 gasdaily hydro", "shorthand": "miso-51-gasdaily-hydro", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(ABLATION TWIN of 2026-07-09-miso-51-gasdaily-hydro) Rule-20 zero-forcing reference solve of the miso-51 recipe (gas_daily_shape[MISO] + hydro 2024-backfill/EIA-930 repin on the re-derived measured coal sigmoid): every merchant commitment floor/bridge OFF, keeping only nuclear must-run, CHP steam-following and coal take-or-pay. The keeper-vs-twin per-class delta shows what each floor buys; the coal over-run persists with all floors off (economic merit, not forcing), consistent with C8 (~0.1-0.2% coal forced).", "file": "frontend/data/backcast/runs/2026-07-09-miso-51-gasdaily-hydro-ablation.js", "id": "2026-07-09-miso-51-gasdaily-hydro-ablation", "iso": "MISO", "label": "miso 51 gasdaily hydro ablation", "shorthand": "miso-51-gasdaily-hydro-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "MISO 52 PROBE (not promoted; keeper stays miso-49): the miso-51 recipe with ONE code change, zero new parameters -- the coal passthrough sigmoid's gas key held at the MONTHLY (contract-repricing) level while gas units keep bidding the daily HH-shaped price (fuel._gas_series). Built to test miso-51's two-part hypothesis: that the daily-keyed sigmoid (a) suppressed the coal-vs-gas flip days and (b) caused the C4 2024 coal-corr and C3b 2023/24 shape FAILs via coal-offer whipsaw. BOTH REFUTED (disclosed, rules 1/10/11): every scored criterion lands within noise of miso-51 -- COAL_PRB +29.9/+25.1/+25.8 TWh, C4 2024 coal r=0.854 (was 0.856), C3b 0.278/0.289 (was 0.277/0.289) -- and C4 was already failing at miso-50 before any daily shape existed. CORRECTED ATTRIBUTION: the C4/C3b regressions vs miso-49 arrived with the sigmoid re-derive itself. The coal over-run is now demonstrated robust to FIVE independent interventions (measured sigmoid params, daily gas granularity, sigmoid key timescale, hydro completeness, zero-forcing ablation) -- it is pure economic merit ordering from the sigmoid's deep-discount premise: ~70% of PRB capacity sits in mustrun/committed tranches offered ~$15-20/MWh, far below CC at any observed gas price, so the merit order never flips. Determination NOT-YET (same surface as miso-51, re-scored under rubric v2.4). The monthly key is KEPT (structurally correct timescale). NEXT ROOT-CAUSE LANE: adjudicate the deep-discount premise against measured MISO IMM/Potomac SOM coal offer-to-cost markup data -- if real MISO coal offers near cost, the premise (not its parameters) is the wrong market structure for 2023-2025; secondarily the tranche-share decomposition (how much coal capacity legitimately carries a take-or-pay discount). Rule-20 zero-forcing ablation twin registered alongside.", "file": "frontend/data/backcast/runs/2026-07-09-miso-52-sigmoid-monthlykey.js", "id": "2026-07-09-miso-52-sigmoid-monthlykey", "iso": "MISO", "label": "miso 52 sigmoid monthlykey", "shorthand": "miso-52-sigmoid-monthlykey", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(ABLATION TWIN of 2026-07-08-neiso-55-temp-derate) rule-20 zero-forcing ablation -- same keeper config + temp_dependent_derate, all merchant floors/bridges off, 2023-2025", "file": "frontend/data/backcast/runs/2026-07-09-neiso-55-temp-derate.js", "id": "2026-07-09-neiso-55-temp-derate", "iso": "NEISO", "label": "neiso 55 temp derate (ABLATION TWIN)", "shorthand": "neiso-55-temp-derate-ablation", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "(ABLATION TWIN of 2026-07-09-neiso-56-reserve-coopt) rule-20 zero-forcing ablation \u2014 the same neiso-55-keeper-plus-energy_reserve_coopt recipe with all merchant floors/bridges off (nuclear must-run, CHP steam-following, coal take-or-pay kept), 2023-2025. Confirms the co-opt dormancy is not floor-masked: the reserve balance dual is $0.00 in the zero-forcing arm too (tail 0h >$300; storage 0.629/0.559/0.911 TWh).", "file": "frontend/data/backcast/runs/2026-07-09-neiso-56-coopt-ablation.js", "id": "2026-07-09-neiso-56-coopt-ablation", "iso": "NEISO", "label": "neiso 56 coopt ablation", "shorthand": "neiso-56-coopt-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-neiso-56-coopt-ablation", "date": "2026-07-09", "definition": "NEISO keeper (promoted 2026-07-09, owner decision, rule-1 structural fidelity). The neiso-55 recipe + energy_reserve_coopt \u2014 ISO-NE system-wide energy+reserve co-optimization with the published 3-level nested RCPF demand curves (total-30-min 1,800 MW @ $1,000, total-10-min 1,200 MW @ $1,500, 10-min-spin 600 MW @ $50; Market Rule 1 \u00a7III.2.7A), storage reserve-eligible. The mechanism is DORMANT on 2023-2025 (reserve dual $0.00 in all 26,280 hours; kept although it moves no backcast metric \u2014 the winter-fuel-stack precedent): fit is byte-comparable to neiso-55 and the determination is identical, CALIBRATED-WITH-CAVEATS (C2 commercial-band; C3c/C5b ledgered \u2014 both closure paths now proven dormant, the caveats are irreducible on the train years by any admissible mechanism identified to date).", "file": "frontend/data/backcast/runs/2026-07-09-neiso-56-reserve-coopt.js", "id": "2026-07-09-neiso-56-reserve-coopt", "iso": "NEISO", "label": "neiso 56 reserve coopt", "market_story": "energy_reserve_coopt adds the real ISO-NE clearing structure: energy and operating reserves co-optimize against the published nested RCPF demand curves, and a reserve-short hour would stack the penalty factor into the LMP while paying reserve value to storage. On 2023-2025 the ample NEISO fleet clears the 1,800/1,200/600 MW requirements out of idle thermal headroom at zero opportunity cost in every hour \u2014 even the January-2025 cold-snap hours with the gas cold-snap derate active \u2014 so the mechanism prices nothing and moves nothing: keeper-vs-twin class deltas are the same small floor effects as the neiso-55 pair, with the reserve dual $0.00 in both arms.", "shorthand": "neiso-56-reserve-coopt", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "D-3 zero-forcing ablation twin of pjm-94 (CLAUDE.md rule 20): the pjm94_stgas_netload_drag recipe verbatim with every merchant floor/bridge/drag neutralized (ScenarioConfig.as_zero_forcing_ablation; off-list from the D-2 mechanism registry incl. gas_st_netload_drag), structural protected set kept. Registered alongside the keeper candidate for the E9 keeper-vs-twin delta \u2014 quantifies what the all-hours ST_GAS net-load drag + CT net-load drag buy per class. [2026-07-09 v2 re-solve, full 2023-2025 span (rule 16). E9 keeper-vs-twin: the drags buy ST_GAS +3.3/+3.8/+4.6 TWh/yr (5.1/4.3/7.1 -> 8.4/8.1/11.7), relocated from CC_REGULAR -1.5/-1.2/-2.2 and CT_PEAKER -1.6/-1.3/-2.3.]", "file": "frontend/data/backcast/runs/2026-07-09-pjm-94-stgas-drag.js", "id": "2026-07-09-pjm-94-stgas-drag", "iso": "PJM", "label": "pjm 94 stgas drag", "shorthand": "pjm-94-stgas-drag", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-pjm-94-stgas-drag", "date": "2026-07-09", "definition": "PJM 94 all-hours ST_GAS net-load reliability-commitment drag on the pjm-90 recipe (resolves #1483 / G-21). Enables gas_st_netload_drag with PJM's own hinge clip(0.01029*netGW - 0.7263, 0, 0.39) fit from measured overnight CF vs EIA-930 PJM net-load (derive_pjm_st_gas_netload_drag.py; rule 25 PJM-own coeffs, rule 11 zero residual-fit). A min-gen FLOOR (offers/prices untouched) keyed to net-load \u2014 the ERCOT/NEISO keeper mechanism, NOT the fake sub-SRMC band #1483 warned against; forward-native (#10/#13). Rule 19 drops the pjm-89 overnight h0-6 ST_GAS reliability limbs (no stacking). Diagnosis: measured ST_GAS 8.1/13.0/15.0 TWh vs pjm-90 5.1/4.4/7.4, fleet online 293-337/365 days (weeks-to-months run-lengths, only 9-19% of energy on temp-flagged days). Otherwise pjm-90 verbatim. [2026-07-09 v2 re-solve: full 2023-2025 span restored (rule 16) after the 2025-only registration; meta.json now round-trips gas_st_drag_overrides so the PJM-fit hinge replays exactly (the first replay attempt silently fell back to the default hinge).]", "file": "frontend/data/backcast/runs/2026-07-09-pjm-94-stgas-netload.js", "id": "2026-07-09-pjm-94-stgas-netload", "iso": "PJM", "label": "pjm 94 stgas netload", "shorthand": "pjm-94-stgas-netload", "years": [2023, 2024, 2025]}, {"date": "2026-07-09", "definition": "D-3 zero-forcing ablation twin of pjm-95 (CLAUDE.md rule 20): the pjm95_stgas_drag_tempderate recipe verbatim (pjm-94 + temp_dependent_derate=True) with every merchant floor/bridge/drag neutralized (ScenarioConfig.as_zero_forcing_ablation; off-list from the D-2 mechanism registry incl. gas_st_netload_drag), structural protected set kept. temp_dependent_derate itself is not a forcing floor (a capacity/availability reshape) so it stays on unchanged. Registered alongside the pjm-95 keeper candidate for the E9 keeper-vs-twin delta -- quantifies what the all-hours ST_GAS net-load drag + CT net-load drag buy on top of the temp-derated capacity envelope.", "file": "frontend/data/backcast/runs/2026-07-09-pjm-95-ablation-twin.js", "id": "2026-07-09-pjm-95-ablation-twin", "iso": "PJM", "label": "pjm 95 ablation twin", "shorthand": "pjm-95-ablation-twin", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-09-pjm-95-ablation-twin", "date": "2026-07-09", "definition": "PJM 95 ST_GAS net-load drag (pjm-94) + temperature-dependent derate: the pjm-94 recipe verbatim with temp_dependent_derate=True added to target the one remaining load-bearing FAIL (C3c price tail, 2025 0h vs 51h >$200). temp_dependent_derate is a physically-derived per-class dry-bulb capacity curve (arXiv:2311.07001, CPUC R.21-10-002; capacity-neutral CC/CT reshape + additive hot-hour COAL/ST_GAS derate) that improved the 2025 C3c tail 0h->19h on the pjm-90 recipe (pjm-93). Tests whether the ST_GAS drag and the temp derate compose. Otherwise pjm-94 verbatim. [2026-07-09 v2 re-solve, full 2023-2025 span (rule 16), re-scored under rubric v2.4: C3b duration/shape passes all years (pjm-94 FAILs 2025 at NRMSE 0.217); C3a 2025 -13.2% vs pjm-94 -14.9% (both FAIL on the load-weighted basis); C3c DA tail 2025 19h vs 51h (pjm-94 0h), RT companions 2/6, 12/18, 19/59 - improves every year. ST_GAS cost of the temp derate -0.05/-0.01/-0.19 TWh/yr (class <2% of load, non-gated). meta.json now round-trips gas_st_drag_overrides (replay fidelity).] [2026-07-09 PROMOTED to PJM keeper (owner GO): attested (zero-DOF temp-derate ledger entry), twin linked, v2.4 determination NOT-YET on C1 CC_REGULAR 2023/24 + C3a/C3c 2025 - strictly dominates pjm-94 (C3b all-years PASS, tail 0h->19h).]", "file": "frontend/data/backcast/runs/2026-07-09-pjm-95-temp-derate.js", "id": "2026-07-09-pjm-95-temp-derate", "iso": "PJM", "label": "pjm 95 temp derate", "shorthand": "pjm-95-temp-derate", "years": [2023, 2024, 2025]}, {"date": "2026-07-10", "definition": "(PROBE \u2014 ZERO-FORCING ABLATION TWIN of 2026-07-10-caiso-70-g61b-decrowd) Every merchant floor/bridge off (nuclear must-run, CHP steam-following, coal take-or-pay preserved). Reproduces the caiso-69 ablation within solver noise (CT_PEAKER 2.017/1.411/1.009 vs 1.987/1.411/0.984 TWh) \u2014 recipe-fidelity check passed; the startup-aware flag is inert under zero-forcing as expected. Twin-vs-main delta attribution: ablation clears +0.3-0.4 GW more CT in the evening ramp h18-21 and ~+0.3 GW more CC across the day while importing 1.0-1.4 GW less in the same evening hours \u2014 the bridge's floors suppress domestic evening thermal via the P0-run-pattern/P1-startup-amortization and seam substitution, not via midday pocket headroom (see main sidecar for the refuted de-crowding hypothesis and redirect).", "file": "frontend/data/backcast/runs/2026-07-10-caiso-70-g61b-ablation.js", "id": "2026-07-10-caiso-70-g61b-ablation", "iso": "CAISO", "label": "caiso 70 g61b ablation", "shorthand": "caiso-70-g61b-ablation", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-10-caiso-70-g61b-ablation", "date": "2026-07-10", "definition": "(PROBE \u2014 pre-registered A/B, negative result) G-61b de-crowding main -- caiso-69 recipe (SP15-split topology, ct_netload_drag=False per-run override) + caiso_ra_bridge_startup_aware=True single delta, 2023-2025. HYPOTHESIS (from caiso-69's corrected redirect): the RA must-offer bridge's forced CC min-gen crowds CT_PEAKER out of the pockets \u2014 releasing the phantom-micro-run share should let pocket CTs clear on merit. RESULT: the release ENGAGED exactly as caiso-63/66 measured (D-2 bridge forced CC 3.62/3.46 -> 2.26/2.02/1.56 TWh, -37/-42/-45%) and CT_PEAKER DID NOT MOVE (0.90/0.92/0.82 vs caiso-69's 0.89/0.91/0.79; actual 4.56/5.24/3.09; ablation ceiling 2.02/1.41/1.01). Pocket LMPs and the tail are also unchanged (LA_BASIN 70.05/47.65/51.45 vs caiso-69 70.18/47.82/51.26; hrs>200 540/0/0 vs 530/0/0). The de-crowding hypothesis is REFUTED: bridge headroom is not what keeps peakers out. ATTRIBUTION of the ablation's CT lift (the signal that motivated this probe): hod deltas show the ablation's extra CT clears in the EVENING RAMP h18-21 (+0.3-0.4 GW) paired with an import pull-back (-1.0 to -1.4 GW same hours), CC also up ~+0.3 GW across the day \u2014 whole-bridge removal changes the P0 run pattern/P1 startup amortization and the seam substitution, i.e. a commitment-posture/seam effect, NOT midday pocket headroom. Redirect (handoff probe #2): the CT gap is an AS/reserve-dispatch channel (RTPD/RUC-like awards -> energy, driven by measured CAISO AS procurement) and/or the evening commitment posture (belly-probe: evening CC deficit +1.9/+1.2/+0.3 GW) \u2014 the split topology plus bridge-side releases cannot form it. C7 CT shape still FAILs (profile_r 0.76/0.76/0.68 \u2014 the retired drag was carrying CT's diurnal shape). C8 PASS (bridge remnant 3.7/3.1/2.4% of CC). FIRST CAISO RUN WITH C6 GOVERNANCE PASS: bundle carries the rubric governance attestation + the caiso-65 DOF ledger (drag entry marked INERT; startup-aware adds zero free parameters). Scored under rubric v2.4 (caiso-69 scored under v2.2 \u2014 C5a CO2 is FAIL here where v2.2 gave commercial-band CAVEAT; cross-version comparisons should re-score, not read stored statuses). Not promotable (8 fails).", "file": "frontend/data/backcast/runs/2026-07-10-caiso-70-g61b-decrowd.js", "id": "2026-07-10-caiso-70-g61b-decrowd", "iso": "CAISO", "label": "caiso 70 g61b decrowd", "shorthand": "caiso-70-g61b-decrowd", "years": [2023, 2024, 2025]}, {"ablation_twin": "2026-07-10-ercot53-hsl-930fill-ablation", "date": "2026-07-10", "definition": "ercot53 HSL known-bad-window 930 fill (single measured-input fix on the ercot52 config, zero config deltas -- coal net-summer derate + ORDC cap-dual adder ON, offer curves untouched): the 2024 HSL parquet's cited known-bad NP6 window (2024-08-20..23) was nulled then linearly interpolated, and with night-bounded endpoints that zeroed 4 days of August solar potential (~810 GWh) and bridged wind flat -- 17 of ercot52's 37 2024 tail hours and most of the Aug-2024 like-for-like monthly error (+62.6%) were phantom scarcity from the hole. build_ercot_hsl.py now fills cited known-bad windows from the measured EIA-930 ERCO hourly series (HSL=GEN inside the window, no fabricated curtailment headroom); the rebuilt parquet is byte-identical outside the window. 2023/2025 inputs untouched, solves reproduce ercot52 (v2.4: C3a -1.0%/-3.6%, C3b 0.109/0.079, C3c 162/5 h). 2024 on rubric v2.4: C3a -0.3% -> -6.8% (still PASS; removing the phantom scarcity reveals the underlying body-under -- the known online-capability wedge), C3b 0.296 -> 0.180, C3c 37 -> 24 h (DA actual 68), Aug demand-weighted 66.15 -> 43.38 vs perfect-model 40.68 (+62.6% -> +6.6%). [2026-07-10 PROMOTED to ERCOT keeper (owner-approved GO, replacing ercot46-clock-steamgas): full 2023-2025 bundle + zero-forcing ablation twin attested, zero new free parameters (DOF ledger inherited from ercot46/51/52). Determination CALIBRATED-WITH-CAVEATS on rubric v2.4 -- 1 criterion inside the commercial-grade band but outside target (C2 system gas/coal volume) and 2 ledgered measured-input caveats (C3c price tail/scarcity, DA-expressible; C5c storage dispatch shape), both open root-cause threads inherited unchanged, not forced closed.]", "file": "frontend/data/backcast/runs/2026-07-10-ercot53-hsl-930fill.js", "id": "2026-07-10-ercot53-hsl-930fill", "iso": "ERCOT", "label": "ercot53 hsl 930fill", "market_story": "Same floor stack as the ercot46 keeper (ST_GAS net-load drag, CT reliability floors, CHP steam-following, coal take-or-pay): legacy gas-steam is committed by real reliability/RUC practice every day and night, CTs hold AS/RUC-deployment energy in load pockets, cogens follow host steam. No new floor this round -- the delta vs ercot52 is a corrected measured renewable input, not forcing.", "shorthand": "ercot53-hsl-930fill", "years": [2023, 2024, 2025]}, {"date": "2026-07-10", "definition": "(ABLATION TWIN of 2026-07-10-ercot53-hsl-930fill) (ABLATION TWIN of ercot53 hsl 930fill) zero-forcing reference solve of the identical config (coal net-summer derate + ORDC cap-dual adder, fixed 2024 HSL input with the known-bad window filled from measured EIA-930): every merchant floor/bridge OFF, keeping only nuclear must-run, CHP steam-following and coal take-or-pay (rule 20 / audit D-3).", "file": "frontend/data/backcast/runs/2026-07-10-ercot53-hsl-930fill-ablation.js", "id": "2026-07-10-ercot53-hsl-930fill-ablation", "iso": "ERCOT", "label": "ercot53 hsl 930fill ablation", "shorthand": "ercot53-hsl-930fill-ablation", "years": [2023, 2024, 2025]}];